prisma.$transaction(async tx => {
    const created = await createRun(tx);
    if (graphExecution) {
      await bindExecutionTaskRun(tx, graphExecution, created.id);
      await bindConversationInputs(tx, graphExecution.executionId, graphExecution.inputIds || [], created.id);
    }
    if (request.graphConversation) await bindReadOnlyConversation(tx, request.graphConversation, created.id);
    if (request.graphReview) await bindGraphReviewTaskRun(tx, request.graphReview, created.id);
    return created;
  })

prisma.$transaction(async tx => {
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${original.nodeId} FOR UPDATE`;
    const latest = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: original.id } });
    if (latest.updatedAt.getTime() !== original.updatedAt.getTime() || !isDeepStrictEqual(latest.dispatchMetadata, original.dispatchMetadata)) throw new Error('迁移期间执行归属或阶段改变');
    if (original.claimToken && (await observeExecutionWriter(latest)).kind !== 'exited') throw new Error('迁移前写入者退出证明已改变');
    const current = await projectCapabilityPolicy(original.repository, args.policyFile);
    if (current?.hash !== policy.hash) throw new Error('迁移期间项目配置改变');
    const prior = await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: original.node.runId, idempotencyKey: key } } });
    if (scopeChange && prior) {
      const receipt = object(prior.payload);
      if (receipt.previousPolicyHash !== previousPolicyHash || receipt.originalClaim !== original.claimToken ||
          receipt.candidateCommit !== report.candidateCommit || (receipt.runtimeUpgradeRevision !== undefined) !== runtimeUpgradeAllowed || !isDeepStrictEqual(receipt.runtimePinIds, pins.map(pin => pin.id))) throw new Error('已有授权变更回执属于不同保存点，不能复用或覆盖');
    }
    await tx.taskGraphEvent.upsert({ where: { runId_idempotencyKey: { runId: original.node.runId, idempotencyKey: key } }, update: {},
      create: { runId: original.node.runId, nodeId: original.nodeId, idempotencyKey: key, kind: 'project_capability_scope_approved',
        payload: { ...(runtimeUpgradeAllowed && progress ? { runtimeUpgradeRevision: progress.revision } : {}), ...(scopeChange ? { version: 2, previousPolicyHash } : {}), executionId: original.id, repository: original.repository, snapshotHash: original.node.run.snapshotHash, scope,
          principal, approvedBy: `host-operator:${process.getuid?.()}`, originalClaim: original.claimToken, candidateCommit: report.candidateCommit,
          approvalHash: createHash('sha256').update(JSON.stringify(report)).digest('hex'), runtimePinIds: pins.map(pin => pin.id) } } });
  })

prisma.$transaction(async tx => {
  await assertGraphReviewOwnershipTx(tx, args.nodeId, 'architecture', claimKey, result.taskRunId);
  await tx.taskGraphEvent.create({ data: {
    runId: args.runId, nodeId: args.nodeId, idempotencyKey: resultKey,
    kind: approved ? 'architecture_passed' : 'architecture_failed',
    payload: { ...(workspaceInvalid ? { failureKind: 'ownership_mismatch' } : result.kind === 'classified' ? result.decision : { failureKind: result.kind }), approved, note, reviewerId: review.reviewerId,
      taskRunId: result.taskRunId, claimKey, commits: args.commits, ...(args.definition.deliveryContract === 'agent_owned_v1' ? { inputs: verificationInputs(executions) } : {}) } as Prisma.InputJsonValue,
  } });
  })

prisma.$transaction(async tx => {
    if (!await graphRunCanStartTx(tx, beforeNode.runId)) return null;
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${nodeId} FOR UPDATE`;
    if (!await writerSnapshotMatches(tx, proof)) return null;
    const currentEvents = await tx.taskGraphEvent.findMany({ where: { nodeId, kind: { in: ['conversation_followup_reserved', 'conversation_followup_bound', 'conversation_followup_finished'] } }, orderBy: { id: 'asc' } });
    if (!isDeepStrictEqual(currentEvents, events)) return null;
    const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: nodeId }, include: { executions: true } });
    if (!isDeepStrictEqual([...node.executions].sort((a, b) => a.id.localeCompare(b.id)), [...proof.jobs].sort((a, b) => a.id.localeCompare(b.id)))) return null;
    for (const job of node.executions) {
      const progress = executionProgress(job.dispatchMetadata);
      if (job.status === 'claimed' || job.status === 'ready' || progress?.state === 'waiting_for_user' && progress.phase === 'implement') continue;
      const pending = await pendingConversationInputs(tx, node.runId, job.id);
      if (!pending.length || !job.childTaskId) continue;
      const previous = await tx.taskGraphEvent.findMany({ where: { runId: node.runId, kind: 'conversation_followup_reserved',
        payload: { path: ['executionId'], equals: job.id } }, orderBy: { createdAt: 'desc' } });
      const batchIdentity = createHash('sha256').update(JSON.stringify({ inputs: Array.from(new Set(pending.map(input => input.rootInputId))).sort(), candidate: progress?.candidateCommit,
        state: progress?.state, failure: progress?.lastFailure })).digest('hex');
      const attempts = previous.filter(event => event.payload && typeof event.payload === 'object' && !Array.isArray(event.payload) && event.payload.batchIdentity === batchIdentity);
      if (attempts.length >= 2 || attempts[0] && Date.now() - attempts[0].createdAt.getTime() < 15_000) return null;
      const event = await tx.taskGraphEvent.create({ data: { runId: node.runId, nodeId: node.id,
        kind: 'conversation_followup_reserved', idempotencyKey: `conversation-followup:${job.id}:${batchIdentity}:${attempts.length}`,
        payload: { executionId: job.id, expectedRevision: progress?.revision, inputIds: pending.map(input => input.id), worker, batchIdentity, attempt: attempts.length + 1 } } });
      if (!progress) throw new Error('Conversation requires versioned execution ownership');
      await tx.taskGraphExecution.update({ where: { id: job.id }, data: { dispatchMetadata: metadataWithProgress(job.dispatchMetadata,
        { ...progress, revision: progress.revision + 1, worker, workerReleasedAt: undefined,
          conversation: { kind: 'reserved', reservationId: event.id } }) } });
      return { job, event, pending };
    }
    return null;
  })

prisma.$transaction(async tx => {
    const original = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId } });
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${original.nodeId} FOR UPDATE`;
    const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
    const run = await tx.taskRun.findUniqueOrThrow({ where: { id: taskRunId } });
    if (run.taskId !== job.childTaskId || !['completed', 'failed', 'stopped', 'interrupted'].includes(run.status)) throw new Error('Conversation run has no terminal result');
    await tx.taskGraphEvent.upsert({ where: { runId_idempotencyKey: { runId: job.node.runId, idempotencyKey: `conversation-turn:${taskRunId}:result` } }, update: {}, create: {
      runId: job.node.runId, nodeId: job.nodeId, idempotencyKey: `conversation-turn:${taskRunId}:result`, kind: 'conversation_turn_result',
      payload: { executionId, taskRunId, status: run.status, summary: run.summary } } });
    const progress = executionProgress(job.dispatchMetadata);
    const currentOwner = progress?.conversation?.kind === 'running' ? progress.conversation.taskRunId === run.id : job.taskRunId === run.id && progress?.conversationOwnerRunId === run.id;
    if (progress && run.status === 'completed' && currentOwner) await tx.taskGraphExecution.update({ where: { id: job.id }, data: {
      dispatchMetadata: metadataWithProgress(job.dispatchMetadata, { ...progress, conversationOwnerRunId: taskRunId }) } });
  })

prisma.$transaction(async tx => {
      const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
      await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${job.nodeId} FOR UPDATE`;
      await tx.$queryRaw`SELECT id FROM "TaskRun" WHERE id = ${run.id} FOR UPDATE`;
      const latestRun = await tx.taskRun.findUniqueOrThrow({ where: { id: run.id } });
      const settled = `conversation-delivery:${receipt.id}:settled`;
      if (await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: receipt.runId, idempotencyKey: settled } } })) return;
      const steeringResult = receipt.kind === 'conversation_steering_started' ? await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: receipt.runId, idempotencyKey: receipt.idempotencyKey + ':result' } } }) : null;
      const rejected = steeringResult?.payload && typeof steeringResult.payload === 'object' && !Array.isArray(steeringResult.payload) && steeringResult.payload.result === 'rejected';
      const uncertain = !rejected && (latestRun.status !== 'completed' || receipt.kind === 'conversation_steering_started' && !steeringResult);
      if (uncertain) {
        const original = await tx.taskGraphEvent.findUniqueOrThrow({ where: { id: inputId } });
        const input = parseInput(original.id, original.payload);
        const key = `conversation-recovery:${original.id}:${run.id}`;
        await tx.taskGraphEvent.upsert({ where: { runId_idempotencyKey: { runId: receipt.runId, idempotencyKey: key } }, update: {}, create: {
          runId: receipt.runId, nodeId: receipt.nodeId, kind: 'conversation_input', idempotencyKey: key,
          payload: { ...input, sourceId: key, receivedState: 'delivery_uncertain',
            content: `上轮消息处理结果未知，原写入者已确认退出。此轮先在原生会话和工作区核对消息是否已执行，再处理尚未完成的部分；禁止机械重放副作用。原消息：\n${input.content}` } } });
      }
      if (receipt.kind === 'conversation_steering_started' && !steeringResult) await tx.taskGraphEvent.create({ data: {
        runId: receipt.runId, nodeId: receipt.nodeId, kind: 'conversation_steering_result', idempotencyKey: receipt.idempotencyKey + ':result',
        payload: { executionId: job.id, taskRunId: run.id, inputId: raw.inputId, result: 'unknown_preserved_for_reconciliation' } } });
      await tx.taskGraphEvent.create({ data: { runId: receipt.runId, nodeId: receipt.nodeId, kind: uncertain ? 'conversation_delivery_uncertain' : 'conversation_delivery_completed',
        idempotencyKey: settled, payload: { executionId: job.id, taskRunId: run.id, inputId: raw.inputId, result: rejected ? 'rejected' : uncertain ? 'uncertain' : 'completed_turn' } } });
    })

prisma.$transaction(async tx => {
    const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
    return pendingConversationInputs(tx, job.node.runId, executionId);
  })

prisma.$transaction(async tx => {
    const original = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId } });
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${original.nodeId} FOR UPDATE`;
    const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
    const progress = executionProgress(job.dispatchMetadata);
    if (!progress || job.claimToken !== claimToken || job.status !== 'claimed') throw new Error('Conversation turn ownership changed');
    const pending = await pendingConversationInputs(tx, job.node.runId, job.id);
    const unknown = await tx.taskGraphEvent.findFirst({ where: { runId: job.node.runId, kind: 'conversation_steering_started',
      payload: { path: ['executionId'], equals: job.id }, NOT: { idempotencyKey: { in: (await tx.taskGraphEvent.findMany({
        where: { runId: job.node.runId, kind: 'conversation_steering_result' }, select: { idempotencyKey: true } })).map(event => event.idempotencyKey.replace(/:result$/, '')) } } } });
    if (unknown) throw new Error('Native steering delivery is unknown; preserve the current run and delivery evidence');
    await tx.taskGraphExecution.update({ where: { id: job.id }, data: { dispatchMetadata: metadataWithProgress(job.dispatchMetadata,
      { ...progress, revision: progress.revision + 1, phase: pending.length ? 'implement' : 'integrate',
        state: pending.length ? 'waiting_for_user' : 'active', candidateCommit,
        ...(pending.length ? { lastFailure: undefined, waitingKind: 'question' as const, waitingMessage: '先处理原话题的新消息。' } : {}) }) ,
      ...(pending.length ? { status: 'attention', issueKind: null } : {}) } });
    if (pending.length) await tx.taskGraphNode.update({ where: { id: job.nodeId }, data: { status: 'attention' } });
    return !pending.length;
  })

prisma.$transaction(async tx => {
        const original = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId } });
        await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${original.nodeId} FOR UPDATE`;
        const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
        if (job.status !== 'claimed' || job.taskRunId !== target.taskRunId || executionProgress(job.dispatchMetadata)?.phase !== 'implement') return null;
        const key = conversationReceiptKey(input.id) + ':steering';
        if (await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: job.node.runId, idempotencyKey: key } } })) return null;
        await tx.taskGraphEvent.create({ data: { runId: job.node.runId, nodeId: job.nodeId, kind: 'conversation_steering_started', idempotencyKey: key,
          payload: { executionId, inputId: input.id, taskRunId: target.taskRunId } } });
        return job.node.runId;
      })

prisma.$transaction(async tx => {
        await tx.taskGraphEvent.create({ data: { runId: reserved, kind: 'conversation_steering_result', idempotencyKey: conversationReceiptKey(input.id) + ':steering:result',
          payload: { executionId, inputId: input.id, taskRunId: target.taskRunId, result } } });
      })

prisma.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "LiveRoom" WHERE id = ${roomId} FOR UPDATE`;
    const room = await tx.liveRoom.findUniqueOrThrow({ where: { id: roomId }, include: { sourceTask: true, members: true } });
    if (!execution.childTaskId || room.sourceTaskId !== execution.childTaskId) throw new Error('Graph conversation belongs to another execution');
    const members = [...room.members];
    for (const approved of participants) {
      const existing = members.find((member) => member.backend === approved.executionBackend && member.harnessType === approved.harnessType &&
        member.runtimeAgentId === (approved.agentId || null));
      if (existing) continue; // Explicitly removed/stopped members are not silently re-enabled.
      const member = await tx.liveRoomMember.create({ data: {
        roomId, memberType: 'local_agent', backend: approved.executionBackend, harnessType: approved.harnessType,
        runtimeAgentId: approved.agentId || null, displayName: approved.agentName || approved.harnessType,
        agentNameSnapshot: approved.agentName || approved.harnessType, role: approved.role,
        roleLabel: '任务图获批参与者', canReply: true, joinStatus: 'joined', presenceStatus: 'idle', sortOrder: members.length + 1,
        codexModel: approved.model || null, codexReasoningEffort: approved.reasoningEffort || null,
        acpxPermissionConfig: JSON.stringify(taskGraphAgentReviewPermissionConfig),
      } });
      members.push(member);
    }
    await tx.liveRoom.update({ where: { id: roomId }, data: {
      currentSpeakerMemberId: room.currentSpeakerMemberId || members.find((member) => member.canReply && member.joinStatus === 'joined')?.id,
      ownerUserId: room.ownerUserId || room.sourceTask?.ownerUserId,
    } });
    return members;
  })

prisma.$transaction(async tx => {
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${job.nodeId} FOR UPDATE`;
    const current = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: job.id } });
    const existing = executionProgress(current.dispatchMetadata);
    if (existing) return existing;
    if (!['ready', 'attention'].includes(current.status) || !current.worktreePath || !current.worktreeBranch) throw new Error('Legacy execution is not paused in a known workspace');
    if (await tx.taskRun.count({ where: { OR: [ ...(current.taskRunId ? [{ id: current.taskRunId }] : []),
      ...(current.childTaskId ? [{ taskId: current.childTaskId }] : []) ], status: { in: ['pending', 'running', 'waiting_for_input'] } } })) throw new Error('Legacy TaskRun is still active');
    await args.assertWriterExited();
    await graphGit(current.repository, 'merge-base', '--is-ancestor', current.baseCommit, args.workspaceBase);
    const checked = await inspectJobWorktree({ repoPath: current.repository, runId: job.node.runId, jobId: job.id,
      baseCommit: args.workspaceBase, resumeCommit: args.previousCandidateCommit });
    if (checked.path !== current.worktreePath || checked.branch !== current.worktreeBranch) throw new Error('Recorded legacy workspace identity mismatch');
    const candidateCommit = await commitJobWorktree({ repoPath: current.repository, runId: job.node.runId, jobId: job.id,
      message: `Adopt current task graph candidate ${job.node.key}/${job.key}` });
    const progress = { ...initialExecutionProgress(), phase: 'implement' as const,
      state: current.status === 'ready' ? 'ready' as const : 'waiting_decision' as const,
      candidateCommit, workspaceBase: args.workspaceBase, ...(current.taskRunId ? { taskRunId: current.taskRunId } : {}),
    };
    const claimToken = current.claimToken || (current.status === 'attention' ? `adoption:${randomUUID()}` : null);
    await tx.taskGraphExecution.update({ where: { id: job.id }, data: { claimToken, dispatchMetadata: metadataWithProgress(current.dispatchMetadata, progress) } });
    await tx.taskGraphEvent.create({ data: { runId: job.node.runId, nodeId: job.nodeId,
      kind: 'execution_progress_adopted', idempotencyKey: `execution:${job.id}:progress-adopted`,
      payload: { executionId: job.id, previousCandidateCommit: args.previousCandidateCommit,
        observedHead: checked.head, candidateCommit, workspaceBase: args.workspaceBase,
        authorization: args.authorization, claimToken, taskRunId: current.taskRunId, revision: progress.revision,
        ownership: { path: checked.path, branch: checked.branch, writerExited: true } },
    } });
    return progress;
  }, { timeout: 30000 })

prisma.$transaction(async tx => {
    const [lock] = await tx.$queryRaw<{ locked: boolean }[]>`SELECT pg_try_advisory_xact_lock(hashtext(${`graph-reply-topic:${binding.id}`})) AS locked`;
    if (!lock.locked) return null;
    const existing = await tx.taskRunFeishuRelay.findFirst({ where: { bindingId: binding.id, messageId: { not: null } }, orderBy: { createdAt: 'asc' } });
    return deliverProgressCard({ bindingId: binding.id, runId: execution.node.runId, childTaskId,
      chatId: binding.chatId, rootMessageId, messageId: existing?.messageId,
      card: { schema: '2.0', config: { update_multi: true }, header: { template: 'orange', title: { tag: 'plain_text', content: '任务进度' } },
      body: { elements: [{ tag: 'markdown', content: detail.split('\n')[0].slice(0, 300) },
        { tag: 'collapsible_panel', expanded: false, header: { title: { tag: 'plain_text', content: '技术详情' } }, elements: [{ tag: 'markdown', content: detail }] }] } } });
  }, { timeout: 25_000 })

prisma.$transaction(async tx => {
    const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: args.executionId } });
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${job.nodeId} FOR UPDATE`;
    const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: job.nodeId } });
    if (node.runId !== args.runId || node.key !== args.nodeKey) throw new Error('Implementation target mismatch');
    if (job.status !== 'claimed' || job.claimToken !== args.claimToken) throw new Error('Implementation claim mismatch');
    await tx.taskGraphEvent.create({ data: { runId: args.runId, nodeId: job.nodeId,
      idempotencyKey: `execution:${job.id}:implementation:${args.claimToken}`, kind: 'implementation_blocked',
      payload: { recoveryKind: 'implementation', blockedPhase: args.blockedPhase || 'implementation', executionId: job.id,
        checkpointCommit: args.checkpointCommit, workspaceBase: args.workspaceBase, taskRunId: args.taskRunId,
        claimToken: args.claimToken, result: args.result } } });
    await tx.taskGraphExecution.update({ where: { id: job.id }, data: { status: 'attention', issueKind: args.result.blockerKind } });
    await tx.taskGraphNode.update({ where: { id: job.nodeId }, data: { status: 'attention' } });
  })

prisma.$transaction(async (tx) => {
    await tx.$queryRaw`SELECT id FROM "TaskGraphRun" WHERE id = ${run.id} FOR UPDATE`;
    const current = await tx.taskGraphRun.findUniqueOrThrow({ where: { id: run.id } });
    if (current.snapshotHash !== args.definition.adoptRun!.snapshotHash) throw new Error('原运行版本已变化');
    const key = { runId: run.id, idempotencyKey: 'issues:source:adopted' };
    const existing = await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: key } });
    if (existing) {
      if ((existing.payload as { source: IssueSource }).source.hash !== args.definition.issueSource!.hash) throw new Error('已有不同来源关联');
      return;
    }
    await tx.taskGraphEvent.create({ data: { ...key, kind: 'issue_source_adopted', payload: {
      source: args.definition.issueSource as unknown as Prisma.InputJsonValue, originalSnapshotHash: run.snapshotHash,
      proposalId: args.proposalId, actorId: args.actorId,
    } } });
  })

prisma.$transaction(async (tx) => {
      await tx.taskGraphNode.updateMany({ where: { runId, key: { in: Array.from(blocked) }, status: { in: ['ready', 'planned'] } }, data: { status: 'attention' } });
      await tx.taskGraphExecution.updateMany({ where: { node: { runId, key: { in: Array.from(blocked) }, status: 'attention' }, status: { in: ['ready', 'planned'] } }, data: { status: 'attention', issueKind: 'issue_source_changed' } });
    })

prisma.$transaction(async tx => {
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${event.nodeId} FOR NO KEY UPDATE`;
    return syncCurrentIssueDelivery(eventId, request);
  }, { timeout: 120_000 })

prisma.$transaction(async tx => {
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${event.nodeId} FOR NO KEY UPDATE`;
    return syncCurrentIssueReopen(eventId, request);
  }, { timeout: 120_000 })

prisma.$transaction(async tx => {
        const [lock] = await tx.$queryRaw<{ locked: boolean }[]>`SELECT pg_try_advisory_xact_lock(hashtext(${`graph-notification:${id}`})) AS locked`;
        if (!lock.locked) return;
        const event = await tx.taskGraphEvent.findUniqueOrThrow({ where: { id } });
        const receiptKey = { runId: event.runId, idempotencyKey: `notification-delivered:${id}` };
        if (await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: receiptKey } })) return;
        const notification = parseNotification(event.payload);
        const feishu = await import('./feishu');
        switch (notification.kind) {
          case 'child_topic': {
            if (!await feishu.ensureGraphChildTopic(notification)) throw new Error('Repository group is not registered; notification remains pending');
            break;
          }
          case 'child_progress': {
            const sent = await feishu.deliverGraphChildProgress(notification.childTaskId, notification.eventKey, notification.text);
            if (!sent) throw new Error('Child topic not yet available');
            break;
          }
          case 'human_review': await feishu.deliverGraphHumanReviewCard(event.runId, notification.nodeKey); break;
        }
        await tx.taskGraphEvent.create({ data: { ...receiptKey, kind: 'notification_delivered', payload: { notificationId: id } } });
      }, { timeout: 60_000 })

prisma.$transaction(async tx => {
      await tx.$queryRaw`SELECT 1 AS locked FROM pg_advisory_xact_lock(hashtextextended(${'overview-input:' + requestId}, 0))`;
      const key = { runId, idempotencyKey: `overview-input:${requestId}` };
      const old = await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: key } });
      if (old) {
        const saved = old.payload;
        if (!saved || typeof saved !== 'object' || Array.isArray(saved) || saved.executionId !== executionId || saved.actorId !== actorId || saved.content !== content) throw new Error('Overview callback identity reused');
        return { taskId: typeof saved.taskId === 'string' ? saved.taskId : '', eventId: old.id };
      }
      const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
      if (job.node.runId !== runId || !job.childTaskId) throw new Error('Reply target is outside this route');
      const room = await tx.liveRoom.findFirst({ where: { sourceTaskId: job.childTaskId, status: 'active' } });
      if (!room) throw new Error('Original Ticket room is not ready');
      const sourceId = `overview:${requestId}`;
      const metadata = JSON.stringify({ source: 'feishu', feishuSenderOpenId: actorId, feishuMessageId: sourceId, feishuChatId: args.chatId,
        overviewRunId: runId, overviewMessageId: args.messageId });
      const message = await tx.liveRoomMessage.create({ data: { roomId: room.id, messageType: 'user', content, metadata } });
      if (!await receiveGraphTaskMessageTx(tx, { taskId: job.childTaskId, sourceId: `feishu:${sourceId}`, actorId, actorOrigin: 'feishu', content, roomMessageId: message.id, sourceMetadata: metadata })) throw new Error('Ticket input ownership changed');
      const event = await tx.taskGraphEvent.create({ data: { ...key, nodeId: job.nodeId, kind: 'overview_input_received', payload: { executionId, taskId: job.childTaskId, actorId, content, roomMessageId: message.id } } });
      return { taskId: job.childTaskId, eventId: event.id };
    })

prisma.$transaction(async tx => {
    if (!await graphRunCanStartTx(tx, runId)) return null;
    const original = await tx.taskGraphNode.findUniqueOrThrow({ where: { runId_key: { runId, key: nodeKey } } });
