export async function bindReadOnlyConversation(tx: Prisma.TransactionClient, args: { executionId: string; reservationId: string; inputIds: string[] }, taskRunId: string) {
  const original = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: args.executionId } });
  await requireGraphNodeActiveTx(tx, original.nodeId);
  await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${original.nodeId} FOR UPDATE`;
  const reservation = await tx.taskGraphEvent.findUniqueOrThrow({ where: { id: args.reservationId } });
  const binding = parseReservation(reservation.payload);
  const current = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: args.executionId } });
  const progress = executionProgress(current.dispatchMetadata);
  if (progress?.conversation?.reservationId !== args.reservationId || progress.conversation.kind !== 'reserved' ||
      progress.worker?.nonce !== binding.worker.nonce || ['claimed', 'ready'].includes(current.status)) throw new Error('Conversation reservation ownership changed');
  if (reservation.kind !== 'conversation_followup_reserved' || binding.executionId !== args.executionId ||
    JSON.stringify(binding.inputIds) !== JSON.stringify(args.inputIds)) throw new Error('Invalid conversation reservation');
  await tx.taskGraphEvent.create({ data: { runId: reservation.runId, nodeId: reservation.nodeId,
    idempotencyKey: `conversation-followup:${reservation.id}:run`, kind: 'conversation_followup_bound', payload: { executionId: args.executionId, taskRunId } } });
  await bindConversationInputs(tx, args.executionId, args.inputIds, taskRunId);
  await tx.taskGraphExecution.update({ where: { id: current.id }, data: { dispatchMetadata: metadataWithProgress(current.dispatchMetadata,
    { ...progress, conversation: { kind: 'running', reservationId: args.reservationId, taskRunId } }) } });
}

export async function conversationInputsByIds(tx: Prisma.TransactionClient, runId: string, executionId: string, ids: string[]) {
  const inputs = await tx.taskGraphEvent.findMany({ where: { id: { in: ids }, runId, kind: 'conversation_input',
    payload: { path: ['executionId'], equals: executionId } }, orderBy: [{ createdAt: 'asc' }, { id: 'asc' }] });
  return inputs.map(input => parseInput(input.id, input.payload));
}

export async function pendingConversationInputs(tx: Prisma.TransactionClient, runId: string, executionId: string): Promise<ConversationInput[]> {
  const ids = await tx.$queryRaw<{ id: string }[]>(Prisma.sql`SELECT i.id FROM "TaskGraphEvent" i
    WHERE i."runId" = ${runId} AND ${unassignedInput} AND i.payload->>'executionId' = ${executionId}
    ORDER BY i."createdAt", i.id LIMIT 50`);
  const inputs = await tx.taskGraphEvent.findMany({ where: { id: { in: ids.map(item => item.id) } }, orderBy: [{ createdAt: 'asc' }, { id: 'asc' }] });
  return inputs.map(input => parseInput(input.id, input.payload));
}

export async function receiveGraphTaskMessageTx(tx: Prisma.TransactionClient, args: GraphTaskMessageInput) {
  const original = await tx.taskGraphExecution.findUnique({ where: { childTaskId: args.taskId }, include: { node: true } });
  if (!original) return false;
  await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${original.nodeId} FOR UPDATE`;
  const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: original.id }, include: { node: { include: { run: true } } } });
  const progress = executionProgress(job.dispatchMetadata);
  await tx.taskGraphEvent.upsert({ where: { runId_idempotencyKey: { runId: job.node.runId,
    idempotencyKey: `conversation-input:${job.id}:${args.sourceId}` } }, update: {}, create: {
    runId: job.node.runId, nodeId: job.nodeId, kind: 'conversation_input', idempotencyKey: `conversation-input:${job.id}:${args.sourceId}`,
    payload: { executionId: job.id, sourceId: args.sourceId, actorId: args.actorId, actorOrigin: args.actorOrigin || 'room', content: args.content, sourceMetadata: args.sourceMetadata || null,
      ...(args.roomMessageId ? { roomMessageId: args.roomMessageId } : {}), receivedPhase: progress?.phase || 'prepare', receivedState: progress?.state || job.status },
  } });
  return true;
}

export async function bindConversationInputs(tx: Prisma.TransactionClient, executionId: string, inputIds: string[], taskRunId: string) {
  const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
  const pending = await pendingConversationInputs(tx, job.node.runId, job.id);
  for (const id of inputIds) {
    if (!pending.some(input => input.id === id)) throw new Error('Conversation input already claimed or belongs to another task');
    await tx.taskGraphEvent.create({ data: { runId: job.node.runId, nodeId: job.nodeId, kind: 'conversation_input_bound',
      idempotencyKey: conversationReceiptKey(id), payload: { executionId, inputId: id, taskRunId, delivery: 'turn' } } });
  }
}

export async function recoverConversationInputs(tx: Prisma.TransactionClient, executionId: string, taskRunId: string) {
  const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: executionId }, include: { node: true } });
  const bound = await tx.taskGraphEvent.findMany({ where: { runId: job.node.runId, kind: { in: ['conversation_input_bound', 'conversation_steering_started'] },
    payload: { path: ['taskRunId'], equals: taskRunId } } });
  for (const receipt of bound) {
    if (receipt.kind === 'conversation_steering_started') {
      const result = await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: job.node.runId, idempotencyKey: receipt.idempotencyKey + ':result' } } });
      if (result?.payload && typeof result.payload === 'object' && !Array.isArray(result.payload) && result.payload.result === 'rejected') continue;
    }
    const value = receipt.payload;
    if (!value || typeof value !== 'object' || Array.isArray(value) || typeof value.inputId !== 'string') throw new Error('Invalid bound conversation input');
    const original = await tx.taskGraphEvent.findUniqueOrThrow({ where: { id: value.inputId } });
    const input = parseInput(original.id, original.payload);
    const key = `conversation-recovery:${original.id}:${taskRunId}`;
    await tx.taskGraphEvent.upsert({ where: { runId_idempotencyKey: { runId: job.node.runId, idempotencyKey: key } }, update: {}, create: {
      runId: job.node.runId, nodeId: job.nodeId, kind: 'conversation_input', idempotencyKey: key,
      payload: { ...input, sourceId: key, content: `上轮写入者已确认退出，但未保存处理结果，消息投递可能已经发生。先核对原会话和工作区已执行的操作，不要重复产生副作用。原消息：\n${input.content}`, receivedState: 'delivery_uncertain' } } });
  }
}

export async function authorizedConversationInput(input: ConversationInput, taskId: string, ownerUserId: string | null, db: Prisma.TransactionClient = prisma) {
  if (input.rootInputId !== input.id) {
    const original = await db.taskGraphEvent.findFirst({ where: { id: input.rootInputId, kind: 'conversation_input', payload: { path: ['executionId'], equals: input.executionId } } });
    if (!original) return false;
    input = parseInput(original.id, original.payload);
    if (input.rootInputId !== input.id) return false;
  }
  if (input.actorOrigin === 'platform') return input.actorId === ownerUserId ||
    (await db.user.findUnique({ where: { id: input.actorId }, select: { role: true } }))?.role === 'admin';
  if (!input.roomMessageId) return false;
  const message = await db.liveRoomMessage.findFirst({ where: { id: input.roomMessageId, messageType: 'user', room: { sourceTaskId: taskId } } });
  if (!message || message.content !== input.content || message.metadata !== input.sourceMetadata) return false;
  if (input.actorOrigin === 'room') return message.senderMemberId === input.actorId && input.sourceId === `room:${message.id}`;
  let metadata: unknown;
  try { metadata = JSON.parse(message.metadata || 'null'); } catch { return false; }
  return !!metadata && typeof metadata === 'object' && 'source' in metadata && metadata.source === 'feishu' &&
    'feishuSenderOpenId' in metadata && metadata.feishuSenderOpenId === input.actorId &&
    'feishuMessageId' in metadata && input.sourceId === `feishu:${metadata.feishuMessageId}`;
}

export async function authorizedMaterialHandoffInput(input: ConversationInput, taskId: string, ownerUserId: string | null, db: Prisma.TransactionClient = prisma) {
  if (!await authorizedConversationInput(input, taskId, ownerUserId, db)) return false;
  if (input.rootInputId !== input.id) {
    const original = await db.taskGraphEvent.findFirst({ where: { id: input.rootInputId, kind: 'conversation_input', payload: { path: ['executionId'], equals: input.executionId } } });
    if (!original) return false;
    input = parseInput(original.id, original.payload);
  }
  if (input.actorOrigin === 'platform') return true;
  if (input.actorOrigin !== 'feishu') return false;
  let metadata: unknown;
  try { metadata = JSON.parse(input.sourceMetadata || 'null'); } catch { return false; }
  const chat = metadata && typeof metadata === 'object' && 'feishuChatId' in metadata && typeof metadata.feishuChatId === 'string' ? metadata.feishuChatId :
    (await db.feishuConversationBinding.findFirst({ where: { liveRoom: { sourceTaskId: taskId }, chatType: 'group' }, select: { chatId: true } }))?.chatId;
  return isFeishuAdmin(input.actorId) || !!chat && await isFeishuGroupAdmin(chat, input.actorId);
}

export async function applyExecutionOutcomeTx(tx: Prisma.TransactionClient, args: ExecutionOutcomeRequest, writerExit?: TaskRunExitProof, expectedExecution?: TaskGraphExecution): Promise<ExecutionProgress> {
    const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: args.executionId } });
    if (!['checkpoint', 'integrated', 'waiting_for_user'].includes(args.outcome.kind)) await requireGraphNodeActiveTx(tx, job.nodeId);
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${job.nodeId} FOR UPDATE`;
    const current = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: job.id }, include: { node: true } });
    const idempotencyKey = `execution:${job.id}:outcome:${args.outcomeId}`;
    const repeated = await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: current.node.runId, idempotencyKey } } });
    if (repeated) {
      const saved = record(repeated.payload);
      if (saved.claimToken !== args.claimToken || saved.expectedRevision !== args.expectedRevision || !isDeepStrictEqual(saved.outcome, args.outcome)) throw new Error('Conflicting execution outcome');
      const progress = executionProgress({ progress: saved.progress });
      if (!progress) throw new Error('Stored outcome has no progress');
      return progress;
    }
    const { node: _node, ...currentExecution } = current;
    if (expectedExecution && !isDeepStrictEqual(currentExecution, expectedExecution)) throw new Error('Execution outcome ownership or revision mismatch: observed candidate changed');
    const before = executionProgress(current.dispatchMetadata) || initialExecutionProgress();
    const admission = ['admitted', 'admission_deferred'].includes(args.outcome.kind) && !!expectedExecution && ['attention', 'integrated'].includes(current.status) && ['attention', 'claimed'].includes(current.node.status) &&
      (['waiting_decision', 'waiting_for_user', 'exhausted'].includes(before.state) || current.status === 'integrated' && ['architecture', 'acceptance'].includes(before.phase) && ['active', 'ready'].includes(before.state)) && !before.conflictRepair;
    const reclassification = args.outcome.kind === 'delivery_reclassified' && current.status === 'integrated' && current.node.status === 'delivered_unverified';
    const reviewRepair = current.status === 'integrated' && ['repair_required', 'retry_exhausted', 'review_retry', 'decision_required'].includes(args.outcome.kind) && ['architecture', 'acceptance'].includes(before.phase);
    const conflictRecovery = current.status === 'attention' && before.state === 'waiting_decision' && before.lastFailure?.code === 'integration_conflict' &&
      (args.outcome.kind === 'repair_required' && !!args.outcome.conflictRepair || args.outcome.kind === 'decision_required' && args.outcome.failure.code === 'integration_conflict');
    if ((!admission && !conflictRecovery && !reviewRepair && !reclassification && current.status !== 'claimed') || current.claimToken !== args.claimToken || before.revision !== args.expectedRevision) throw new Error('Execution outcome ownership or revision mismatch');
    if (args.outcome.kind === 'delivery_reclassified' && (!reclassification || !args.outcome.authorization.trim())) throw new Error('Operator outcome is not authorized for the current state');
    if ((args.outcome.kind === 'integrated' || args.outcome.kind === 'integration_stale') && before.phase !== 'integrate' ||
        args.outcome.kind === 'repair_required' && !['check', 'integrate', 'architecture', 'acceptance'].includes(before.phase) ||
        args.outcome.kind === 'result_incomplete' && !['implement', 'collect_result', 'check'].includes(before.phase)) throw new Error('Execution outcome does not belong to current phase');
    const progress: ExecutionProgress = { ...before, revision: before.revision + 1, state: 'active' };
    delete progress.nextRetryAt;
    const outcome = args.outcome;
    let status = current.status;
    let issueKind: string | null = null;
    if (outcome.kind === 'admission_deferred') {
      if (!admission || !Number.isFinite(Date.parse(outcome.retryAt))) throw new Error('Invalid deferred admission');
      status = current.status; progress.state = before.state; progress.nextRetryAt = outcome.retryAt; progress.lastFailure = completeExecutionFailure(outcome.failure);
    } else if (outcome.kind === 'admitted') {
      if (!admission || !outcome.requestId.trim() || before.state === 'ownership_attention') throw new Error('Invalid admission identity');
      progress.phase = outcome.stage.phase;
      delete progress.lastFailure; delete progress.waitingKind; delete progress.waitingMessage; delete progress.conversation;
      if (outcome.stage.kind === 'review') {
        if (!current.commit || !['architecture', 'acceptance'].includes(before.phase)) throw new Error('Admission requires fixed review candidate');
        status = 'integrated'; progress.review = { kind: 'ready', phase: outcome.stage.phase, candidateCommit: current.commit, claimKey: outcome.stage.claimKey };
      } else {
        if (['architecture', 'acceptance'].includes(before.phase)) throw new Error('Review cannot be admitted as implementation');
        status = 'ready'; progress.state = 'ready'; delete progress.review;
      }
    } else if (outcome.kind === 'continue_work') {
      if (!['implement', 'collect_result'].includes(before.phase) || !/^[a-f0-9]{64}$/.test(outcome.fingerprint) || !outcome.note.trim()) throw new Error('Invalid normal work continuation');
      const unchangedTurns = before.lastFailure?.code !== 'invalid_result' && before.continuation?.fingerprint === outcome.fingerprint ? before.continuation.unchangedTurns + 1 : 0;
      progress.continuation = { fingerprint: outcome.fingerprint, unchangedTurns };
      progress.phase = 'implement';
      delete progress.lastFailure; delete progress.waitingKind; delete progress.waitingMessage;
      if (unchangedTurns >= maxUnchangedWorkTurns) {
        status = 'attention'; progress.state = 'waiting_for_user'; progress.waitingKind = 'answered';
        progress.waitingMessage = '连续轮次未产生新的代码、资料或用户输入，已停止空转并保留原会话。';
      } else { status = 'ready'; progress.state = 'ready'; }
    } else if (outcome.kind === 'waiting_for_user') {
      if (!['implement', 'collect_result'].includes(before.phase)) throw new Error('Only implementation turns may wait for user input');
      status = 'attention'; progress.state = 'waiting_for_user'; progress.waitingMessage = outcome.note; progress.waitingKind = outcome.result || 'question';
      if (outcome.failure) progress.lastFailure = completeExecutionFailure(outcome.failure);
      else delete progress.lastFailure;
    } else if (outcome.kind === 'delivery_reclassified') {
      status = 'attention'; issueKind = outcome.failure.code; progress.phase = 'implement'; progress.state = 'waiting_decision';
      progress.lastFailure = completeExecutionFailure(outcome.failure); delete progress.review;
    } else if (outcome.kind === 'checkpoint') {
      progress.phase = outcome.phase;
      if (outcome.worker) { progress.worker = outcome.worker; delete progress.workerReleasedAt; }
      if (outcome.workspaceBase) progress.workspaceBase = outcome.workspaceBase;
      if (outcome.candidateCommit) {
        if (!/^[0-9a-f]{40,64}$/.test(outcome.candidateCommit)) throw new Error('Invalid candidate commit');
        progress.candidateCommit = outcome.candidateCommit;
      }
      if (outcome.runtimeDirectory) progress.runtimeDirectory = outcome.runtimeDirectory;
      if (outcome.conflictRepair === null) delete progress.conflictRepair;
      else if (outcome.conflictRepair) progress.conflictRepair = outcome.conflictRepair;
      if (outcome.conflictRepair === null) delete progress.runtimeDirectory;
    } else if (outcome.kind === 'integrated') {
      if (!/^[0-9a-f]{40,64}$/.test(outcome.commit) || !current.worktreePath || !current.worktreeBranch) throw new Error('Missing integration identity');
      status = 'integrated'; progress.phase = 'architecture'; progress.candidateCommit = outcome.commit;
    } else if (outcome.kind === 'integration_stale') {
      progress.integrationAttempts++;
      progress.lastFailure = completeExecutionFailure(outcome.failure);
      if (progress.integrationAttempts >= executionRetryLimits.integrationAttempts) {
        status = 'attention'; issueKind = 'retry_exhausted'; progress.state = 'exhausted';
      }
    } else if (outcome.kind === 'review_retry') {
      progress.lastFailure = completeExecutionFailure(outcome.failure);
      progress.phase = outcome.phase || before.phase;
      if (!['architecture', 'acceptance'].includes(before.phase)) throw new Error('Review retry is outside a review phase');
      if (progress.platformAttempts >= executionRetryLimits.platformAttempts) {
        status = 'attention'; issueKind = 'retry_exhausted'; progress.state = 'exhausted';
      } else {
        progress.platformAttempts++; progress.state = 'ready';
        if (!current.commit) throw new Error('Review restart has no integrated candidate');
        progress.review = { candidateCommit: current.commit, phase: progress.phase === 'architecture' ? 'architecture' : 'acceptance', claimKey: outcome.claimKey, kind: 'ready' };
      }
    } else if (['platform_retry', 'result_incomplete'].includes(outcome.kind) && 'failure' in outcome && outcome.failure.fingerprint &&
        !(outcome.kind === 'platform_retry' && outcome.failure.blockerCause === 'transient')) {
      const sameFailure = outcome.kind !== 'result_incomplete' || before.lastFailure?.code === outcome.failure.code && before.lastFailure?.detail === outcome.failure.detail;
      const unchangedTurns = sameFailure && before.continuation?.fingerprint === outcome.failure.fingerprint ? before.continuation.unchangedTurns + 1 : 0;
      progress.continuation = { fingerprint: outcome.failure.fingerprint, unchangedTurns };
      progress.lastFailure = completeExecutionFailure(outcome.failure);
      if (outcome.kind === 'platform_retry') progress.platformAttempts++;
      else progress.formatAttempts++;
      if (unchangedTurns >= (outcome.kind === 'result_incomplete' ? executionRetryLimits.formatAttempts : maxUnchangedWorkTurns)) {
        status = 'attention'; progress.state = 'waiting_for_user'; progress.waitingKind = 'answered';
        progress.waitingMessage = '相同输入与相同失败未产生新进展，已停止空转；新消息或有效条件变化可继续原任务。';
      } else {
        status = 'ready'; progress.state = 'ready';
        if (outcome.kind === 'result_incomplete') progress.phase = 'collect_result';
        progress.nextRetryAt = new Date(Date.now() + 1000 * (unchangedTurns + 1)).toISOString();
      }
    } else if (outcome.kind === 'repair_required' && outcome.failure.tree && outcome.failure.fingerprint) {
      const recent = await tx.taskGraphEvent.findMany({ where: { runId: current.node.runId, nodeId: job.nodeId, kind: 'execution_outcome', AND: [
        { payload: { path: ['executionId'], equals: job.id } }, { payload: { path: ['outcome', 'kind'], equals: 'repair_required' } },
      ] }, orderBy: [{ createdAt: 'desc' }, { id: 'desc' }], take: maxUnchangedWorkTurns, select: { payload: true } });
      const stalled = recent.length === maxUnchangedWorkTurns && recent.every(event => {
        const previous = record(record(event.payload).outcome), failure = record(previous.failure);
        return failure.fingerprint === outcome.failure.fingerprint;
      });
      if (!stalled) progress.repairAttempts++;
      progress.phase = outcome.conflictRepair ? 'integrate' : 'implement'; progress.lastFailure = completeExecutionFailure(outcome.failure);
      if (outcome.conflictRepair) { progress.conflictRepair = outcome.conflictRepair; delete progress.runtimeDirectory; }
      if (stalled) {
        status = 'attention'; progress.state = 'waiting_for_user'; progress.waitingKind = 'answered';
        progress.waitingMessage = '相同代码与输入反复产生同一缺陷，已停止空转，原工作资格与现场保留。';
      } else { status = 'ready'; progress.state = 'ready'; }
    } else {
      progress.lastFailure = completeExecutionFailure(outcome.failure);
      if (outcome.kind === 'repair_required' && outcome.conflictRepair) { progress.conflictRepair = outcome.conflictRepair; delete progress.runtimeDirectory; }
      if (outcome.kind === 'decision_required') {
        status = 'attention'; issueKind = outcome.failure.code; progress.state = outcome.failure.code === 'ownership_mismatch' ? 'ownership_attention' : 'waiting_decision';
      } else {
        const budget = outcome.kind === 'result_incomplete' ? 'formatAttempts' : outcome.kind === 'platform_retry' ? 'platformAttempts' : 'repairAttempts';
        const limit = executionRetryLimits[budget];
        if (outcome.kind === 'retry_exhausted' || progress[budget] >= limit) {
          status = 'attention'; issueKind = 'retry_exhausted'; progress.state = 'exhausted';
        } else {
          progress[budget]++;
          progress.phase = outcome.kind === 'result_incomplete' ? 'collect_result' : outcome.kind === 'repair_required' ? outcome.conflictRepair ? 'integrate' : 'implement' : before.phase;
          progress.state = 'ready'; status = 'ready';
          if (outcome.kind === 'platform_retry') progress.nextRetryAt = new Date(Date.now() + 1000 * progress[budget]).toISOString();
        }
      }
    }
    if (status === 'ready' || outcome.kind === 'admitted' || outcome.kind === 'integrated' || outcome.kind === 'review_retry') { delete progress.worker; delete progress.workerReleasedAt; }
    if (status === 'ready' && current.taskRunId && await tx.taskRun.count({ where: { id: current.taskRunId, status: { in: ['pending', 'running', 'waiting_for_input'] } } })) throw new Error('Cannot requeue a live TaskRun');
    if (status === 'ready' && current.taskRunId && !await taskRunExitMatches(tx, current.taskRunId, writerExit)) throw new Error('Cannot requeue a TaskRun without actual writer exit proof');
    await tx.taskGraphExecution.update({ where: { id: current.id }, data: {
      status, issueKind, dispatchMetadata: metadataWithProgress(current.dispatchMetadata, progress),
      ...(status === 'ready' ? { claimToken: null, claimedAt: null, taskRunId: null, sessionId: null } : {}),
      ...(outcome.kind === 'integrated' ? { commit: outcome.commit, evidence: outcome.evidence } : {}),
    } });
    if (status === 'attention' && outcome.kind !== 'admission_deferred') await tx.taskGraphNode.update({ where: { id: job.nodeId }, data: { status: 'attention' } });
    if (status === 'ready' && outcome.kind !== 'admitted') {
      await tx.taskGraphNode.update({ where: { id: job.nodeId }, data: { status: 'claimed' } });
      await tx.taskGraphRun.updateMany({ where: { id: current.node.runId, status: { not: 'paused' } }, data: { status: 'running' } });
    }
    if (outcome.kind === 'decision_required' && ['missing_business_material', 'missing_upstream_input', 'environment_failed', 'scope_change', 'permission_required'].includes(outcome.failure.code)) {
      await tx.taskGraphEvent.create({ data: { runId: current.node.runId, nodeId: job.nodeId,
        idempotencyKey: `${idempotencyKey}:blocked`, kind: 'implementation_blocked',
        payload: { recoveryKind: 'implementation', blockedPhase: outcome.failure.blockedPhase || progress.phase, executionId: job.id,
          checkpointCommit: progress.candidateCommit, workspaceBase: progress.workspaceBase,
          taskRunId: current.taskRunId, claimToken: args.claimToken,
          result: { status: 'blocked', blockerKind: outcome.failure.code, note: outcome.failure.detail } },
      } });
    }
    await tx.taskGraphEvent.create({ data: { runId: current.node.runId, nodeId: job.nodeId, idempotencyKey,
      kind: outcome.kind === 'integrated' ? 'execution_integrated' : 'execution_outcome',
      payload: { ...(outcome.kind === 'integrated' ? { commit: outcome.commit } : {}), executionId: job.id, claimToken: args.claimToken, expectedRevision: args.expectedRevision, outcome, progress } as unknown as Prisma.InputJsonValue,
    } });
    return progress;
}

export async function bindExecutionTaskRun(tx: Prisma.TransactionClient, args: { executionId: string; claimToken: string; revision: number }, taskRunId: string) {
  const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: args.executionId } });
  await requireGraphNodeActiveTx(tx, job.nodeId);
  await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${job.nodeId} FOR UPDATE`;
  const current = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: job.id } });
  const progress = executionProgress(current.dispatchMetadata);
  if (!progress || progress.revision !== args.revision || current.status !== 'claimed' || current.claimToken !== args.claimToken || current.taskRunId) throw new Error('TaskRun execution binding is stale or occupied');
  await tx.taskGraphExecution.update({ where: { id: job.id }, data: {
    taskRunId, dispatchMetadata: metadataWithProgress(current.dispatchMetadata, { ...progress, taskRunId, conversationOwnerRunId: taskRunId }),
  } });
}

export async function pendingReviewRepairTx(tx: Prisma.TransactionClient, nodeId: string) {
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: nodeId }, include: { executions: true, run: true } });
  if (node.status !== 'attention' || !['running', 'attention'].includes(node.run.status) || !node.executions.length || node.executions.some(job => job.status !== 'integrated')) return null;
  const first = executionProgress(node.executions[0].dispatchMetadata)?.review;
  if (!first || first.kind !== 'running') return null;
  const executions: PendingReviewRepairBinding['executions'] = [];
  for (const job of node.executions) {
    const progress = executionProgress(job.dispatchMetadata), review = progress?.review;
    if (!progress || progress.state !== 'active' || progress.phase !== first.phase || !job.commit || progress.candidateCommit !== job.commit ||
        job.issueKind === 'retry_exhausted' || !job.claimToken ||
        review?.kind !== 'running' || review.phase !== first.phase || review.claimKey !== first.claimKey || review.taskRunId !== first.taskRunId || review.candidateCommit !== job.commit) return null;
    executions.push({ id: job.id, revision: progress.revision, claimToken: job.claimToken, commit: job.commit });
  }
  const taskRun = await tx.taskRun.findUnique({ where: { id: first.taskRunId }, include: { participants: true } });
  const taskId = `task-graph-${first.phase === 'architecture' ? 'architecture' : 'review'}-${node.id}`;
  if (!taskRun || taskRun.status !== 'completed' || taskRun.taskId !== taskId) return null;
  const definition = node.run.snapshot as unknown as GraphDefinition;
  const marker = first.phase === 'architecture' ? 'TASK_GRAPH_ARCH_REVIEW' : 'TASK_GRAPH_REVIEW';
  const response = taskRun.participants[0]?.summary || taskRun.summary || '';
  const matches = Array.from(response.matchAll(new RegExp('^' + marker + '[ \\t]+(\\{[^\\r\\n]+\\})[ \\t]*$', 'gm')));
  if (matches.length !== 1) return null;
  let raw: unknown; try { raw = JSON.parse(matches[0][1]); } catch { return null; }
  const decision = classifyReview(raw, graphReviewChecks(definition, node.key, node.executions));
  if (!decision || decision.approved || decision.failureKind !== 'in_scope_defect') return null;
  if (node.executions.some(job => decision.executionIds.includes(job.id) && (executionProgress(job.dispatchMetadata)?.repairAttempts || 0) >= executionRetryLimits.repairAttempts)) return null;
  const evidence = verificationEvidence(node.evidence);
  const required = definition.nodes.find(item => item.key === node.key)?.acceptance.checks;
  if (!evidence || !required || required.some(name => !evidence.checks.some(check => check.name.trim() === name.trim() && check.evidence.trim())) || evidence.checks.every(check => check.passed)) return null;
  if ((await observeTaskRunWriter(first.taskRunId)).kind !== 'exited') throw new Error(`Pending review repair ${node.key}: reviewer writer has not proven exit`);
  for (const job of node.executions) if ((await observeExecutionWriter(job)).kind !== 'exited') throw new Error(`Pending review repair ${node.key}/${job.key}: phase or implementation writer has not proven exit`);
  const binding: PendingReviewRepairBinding = { phase: first.phase, claimKey: first.claimKey, taskRunId: first.taskRunId, executions: executions.sort((a, b) => a.id.localeCompare(b.id)) };
  return { binding, decision, evidence };
}

export async function assertPendingReviewRepairTx(tx: Prisma.TransactionClient, nodeId: string,
  expected: PendingReviewRepairBinding, decision: unknown, evidence: VerificationEvidence) {
  const current = await pendingReviewRepairTx(tx, nodeId);
  if (!current || !isDeepStrictEqual(current.binding, expected) || !isDeepStrictEqual(current.decision, decision) || !isDeepStrictEqual(current.evidence, evidence)) throw new Error('Pending review repair binding, result or evidence changed');
}

export async function assertExecutionWriterExited(tx: Prisma.TransactionClient, job: {
  id: string; nodeId: string; taskRunId: string | null; claimToken: string | null;
  dispatchMetadata: unknown; worktreePath: string | null; worktreeBranch: string | null;
}) {
  const observation = await observeExecutionWriter(job);
  if (observation.kind === 'exited') return;
  const progress = executionProgress(job.dispatchMetadata);
  if (observation.kind === 'unknown' && progress && !progress.worker) {
    const event = await tx.taskGraphEvent.findFirst({ where: { nodeId: job.nodeId, kind: 'execution_progress_adopted', idempotencyKey: `execution:${job.id}:progress-adopted` } });
    const proof = event?.payload;
    if (proof && typeof proof === 'object' && !Array.isArray(proof)) {
      const ownership: unknown = Reflect.get(proof, 'ownership');
      const authorization: unknown = Reflect.get(proof, 'authorization');
      if (ownership && typeof ownership === 'object' && Reflect.get(ownership, 'writerExited') === true &&
          Reflect.get(proof, 'executionId') === job.id && Reflect.get(proof, 'taskRunId') === job.taskRunId &&
          Reflect.get(proof, 'revision') === progress.revision && Reflect.get(proof, 'claimToken') === job.claimToken &&
          Reflect.get(proof, 'candidateCommit') === progress.candidateCommit && Reflect.get(proof, 'workspaceBase') === progress.workspaceBase &&
          Reflect.get(ownership, 'path') === job.worktreePath && Reflect.get(ownership, 'branch') === job.worktreeBranch &&
          typeof authorization === 'string' && authorization.trim()) return;
    }
  }
  throw new Error('原执行者仍存活或无法确认退出，不能重复派发');
}

export async function preparationBindingTx(tx: Prisma.TransactionClient, runId: string, nodeKey: string, remediation: PreparationReceipt['remediation']) {
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { runId_key: { runId, key: nodeKey } }, include: { executions: true, run: true } });
  if (!['running', 'attention'].includes(node.run.status) || node.status !== 'attention') throw new PreparationRejected('Preparation requires a paused node in an active approved Run');
  if (node.executions.length !== 1) throw new PreparationRejected('Prepared recovery currently supports exactly one execution; multi-execution nodes require explicit scoped support');
  const job = node.executions[0], progress = executionProgress(job.dispatchMetadata);
  if (progress?.state === 'exhausted' || job.issueKind === 'retry_exhausted') throw new PreparationRejected('Preparation cannot reset exhausted execution');
  if (job.status !== 'attention' || !job.claimToken || !progress || progress.state !== 'waiting_decision' || progress.phase !== 'implement' ||
      !progress.candidateCommit || !progress.workspaceBase || progress.conflictRepair) throw new PreparationRejected('Preparation requires a versioned implement-phase waiting decision with candidate and original ownership');
  const failure = progress.lastFailure;
  if (!failure || (remediation === 'upstream_binding' ? failure.code !== 'missing_upstream_input' : failure.code !== 'environment_failed' || failure.blockerCause !== 'missing_capability') ||
      failure.requiresUserDecision === true || failure.owner !== undefined && failure.owner !== 'platform') throw new PreparationRejected('Preparation is not authorized for this business, permission, ownership or failure kind');
  const dependencies = await tx.taskGraphNode.findMany({ where: { runId, key: { in: node.dependsOn } }, include: { executions: true }, orderBy: { key: 'asc' } });
  if (dependencies.length !== node.dependsOn.length || dependencies.some(item => !['passed', 'delivered_unverified'].includes(item.status))) throw new PreparationRejected('Preparation dependencies have not passed');
  return preparationHash({ nodeId: node.id, snapshotHash: node.run.snapshotHash, executionId: job.id,
    claimToken: job.claimToken, taskRunId: job.taskRunId, baseCommit: job.baseCommit, candidateCommit: progress.candidateCommit,
    workspaceBase: progress.workspaceBase, revision: progress.revision, progress, worktreePath: job.worktreePath,
    worktreeBranch: job.worktreeBranch, dispatchMetadata: job.dispatchMetadata,
    dependencies: dependencies.map(item => ({ id: item.id, status: item.status, commits: item.executions.map(value => ({ id: value.id, commit: value.commit })).sort((a, b) => a.id.localeCompare(b.id)) })) });
}

export async function assertPreparationTx(tx: Prisma.TransactionClient, runId: string, nodeKey: string, eventId: string, validated: PreparationReceipt) {
  const event = await tx.taskGraphEvent.findUniqueOrThrow({ where: { id: eventId } });
  if (event.kind !== 'platform_preparation_registered' || event.runId !== runId) throw new PreparationRejected('Invalid trusted preparation event');
  const receipt = parsePreparationReceipt(event.payload);
  const target = await tx.taskGraphNode.findUniqueOrThrow({ where: { runId_key: { runId, key: nodeKey } }, select: { id: true } });
  if (event.nodeId !== target.id) throw new PreparationRejected('Preparation event node mismatch');
  if (receipt.runId !== runId || receipt.nodeKey !== nodeKey ||
      event.idempotencyKey !== `preparation:${receipt.requestId}`) throw new PreparationRejected('Preparation target mismatch');
  if (await preparationBindingTx(tx, runId, nodeKey, receipt.remediation) !== receipt.bindingHash) throw new PreparationRejected('Stale preparation binding: revision, candidate, failure or dependencies changed');
  if (preparationHash(receipt) !== preparationHash(validated)) throw new PreparationRejected('Preparation receipt changed after artifact validation');
  return receipt;
}

async function preparationRequestTx(tx: Prisma.TransactionClient, receipt: PreparationReceipt, key: string) {
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { runId_key: { runId: receipt.runId, key: receipt.nodeKey } }, select: { id: true } });
  await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${node.id} FOR UPDATE`;
  const previous = await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: receipt.runId, idempotencyKey: key } } });
  return { node, previous };
}

async function preparedReviewBinding(tx: Prisma.TransactionClient, runId: string, nodeKey: string) {
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { runId_key: { runId, key: nodeKey } }, include: { executions: true, run: true } });
  const job = node.executions[0], progress = job && executionProgress(job.dispatchMetadata);
  if (!['attention', 'running'].includes(node.run.status) || node.status !== 'attention' || node.executions.length !== 1 || !job.claimToken || !job.commit ||
      job.status !== 'attention' || progress?.state !== 'exhausted' || progress.phase !== 'acceptance' || progress.candidateCommit !== job.commit ||
      progress.platformAttempts < executionRetryLimits.platformAttempts || progress.lastFailure?.code !== 'review_platform_failure' || progress.lastFailure.requiresUserDecision === true || progress.lastFailure.owner && progress.lastFailure.owner !== 'platform') throw new Error('Prepared review requires an exhausted platform acceptance with unchanged integrated candidate');
  const dependencies = await tx.taskGraphNode.findMany({ where: { runId, key: { in: node.dependsOn } }, include: { executions: true }, orderBy: { key: 'asc' } });
  if (dependencies.length !== node.dependsOn.length || dependencies.some(item => !['passed', 'delivered_unverified'].includes(item.status))) throw new Error('Review dependencies have not passed');
  return { node, job, progress, hash: preparationHash({ snapshotHash: node.run.snapshotHash, job, dependencies }) };
}

async function interruptExitedRun(tx: Prisma.TransactionClient, taskRunId: string) {
  await tx.taskRun.updateMany({ where: { id: taskRunId, status: { in: ['pending', 'running', 'waiting_for_input'] } },
    data: { status: 'interrupted', completedAt: new Date(), summary: 'Previous local writer exited; task graph resumes from preserved progress.' } });
  await tx.taskRunParticipant.updateMany({ where: { taskRunId, status: { in: ['pending', 'running', 'waiting_for_input'] } }, data: { status: 'interrupted' } });
}

export async function bindGraphReviewTaskRun(tx: Prisma.TransactionClient, args: { runId: string; nodeId: string; phase: 'architecture' | 'acceptance'; claimKey: string }, taskRunId: string) {
  await requireGraphRunActiveTx(tx, args.runId);
  await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${args.nodeId} FOR UPDATE`;
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: args.nodeId }, include: { executions: true } });
  if (node.runId !== args.runId || node.status !== 'verifying') throw new Error('Review node no longer owns verification');
  const claim = await tx.taskGraphEvent.findUnique({ where: { runId_idempotencyKey: { runId: args.runId, idempotencyKey: args.claimKey } } });
  if (!claim || claim.nodeId !== node.id || claim.kind !== (args.phase === 'architecture' ? 'architecture_claimed' : 'review_claimed')) throw new Error('Review has no matching durable claim');
  for (const job of node.executions) {
    if (job.status !== 'integrated' || !job.commit || !/^[0-9a-f]{40,64}$/.test(job.commit)) throw new Error('Review input has no integrated commit');
    const previousProgress = executionProgress(job.dispatchMetadata);
    const progress = previousProgress || { ...initialExecutionProgress(), phase: args.phase, workspaceBase: job.baseCommit, candidateCommit: job.commit };
    if (!previousProgress) await tx.taskGraphEvent.create({ data: { runId: args.runId, nodeId: node.id,
      idempotencyKey: `review-progress-adopted:${job.id}`, kind: 'review_progress_adopted', payload: { executionId: job.id, integratedCommit: job.commit, phase: args.phase } } });
    if (progress.review?.kind === 'running') {
      const previous = await tx.taskRun.findUnique({ where: { id: progress.review.taskRunId } });
      if (previous && ['pending', 'running', 'waiting_for_input'].includes(previous.status)) throw new Error('Previous review TaskRun still owns this input');
    }
    if (progress.review?.kind === 'ready' && progress.review.claimKey !== args.claimKey) throw new Error('Review claim was superseded');
    await tx.taskGraphExecution.update({ where: { id: job.id }, data: { claimToken: job.claimToken || `review-owner:${taskRunId}`, dispatchMetadata: metadataWithProgress(job.dispatchMetadata,
      { ...progress, revision: progress.revision + 1, state: 'active', phase: args.phase, candidateCommit: job.commit,
        review: { phase: args.phase, claimKey: args.claimKey, kind: 'running', taskRunId, candidateCommit: job.commit } }) } });
  }
  await tx.taskGraphEvent.create({ data: { runId: args.runId, nodeId: node.id, kind: 'review_dispatched',
    idempotencyKey: `review-dispatched:${taskRunId}`, payload: { ...args, taskRunId } } });
}

export async function assertGraphReviewOwnershipTx(tx: Prisma.TransactionClient, nodeId: string, phase: 'architecture' | 'acceptance', claimKey: string, taskRunId: string) {
  await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${nodeId} FOR UPDATE`;
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: nodeId }, include: { executions: true } });
  if (node.status !== 'verifying' || !node.executions.length || node.executions.some(job => {
    const binding = executionProgress(job.dispatchMetadata)?.review;
    return job.status !== 'integrated' || binding?.kind !== 'running' || binding.phase !== phase || binding.claimKey !== claimKey || binding.taskRunId !== taskRunId || binding.candidateCommit !== job.commit;
  })) throw new Error('Review ownership changed before result publication');
}

export async function applyReviewFailureTx(tx: Prisma.TransactionClient, nodeId: string, args: {
  phase: 'architecture' | 'acceptance'; claimKey: string; identity: string;
  failure: ExecutionFailure; kind: 'platform_failure' | 'protocol_exhausted' | 'decision_required';
}) {
  await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${nodeId} FOR UPDATE`;
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: nodeId }, include: { executions: true } });
  if (node.status !== 'verifying' || !node.executions.length) throw new Error('Review failure no longer owns verification');
  const exhausted = args.kind === 'protocol_exhausted' || args.kind === 'platform_failure' && node.executions.some(job => (executionProgress(job.dispatchMetadata)?.platformAttempts || 0) >= executionRetryLimits.platformAttempts);
  const failure: ExecutionFailure = args.kind === 'platform_failure' ? { ...args.failure, owner: 'platform', requiresUserDecision: false } : args.failure;
  const nextClaim = `${args.claimKey}:platform:${Math.max(...node.executions.map(job => executionProgress(job.dispatchMetadata)?.platformAttempts || 0)) + 1}`;
  for (const job of node.executions) {
    if (job.status !== 'integrated' || !job.commit) throw new Error('Review failure input is not integrated');
    let progress = executionProgress(job.dispatchMetadata);
    if (!progress) {
      progress = { ...initialExecutionProgress(), phase: args.phase, candidateCommit: job.commit, workspaceBase: job.baseCommit };
      await tx.taskGraphEvent.create({ data: { runId: node.runId, nodeId, kind: 'review_progress_adopted', idempotencyKey: `review-failure-adopted:${job.id}`, payload: { executionId: job.id, integratedCommit: job.commit } } });
    }
    const token = job.claimToken || `review-preparation:${nodeId}`;
    if (!executionProgress(job.dispatchMetadata)) await tx.taskGraphExecution.update({ where: { id: job.id }, data: { claimToken: token, dispatchMetadata: metadataWithProgress(job.dispatchMetadata, progress) } });
    else if (!job.claimToken) throw new Error('Versioned review has no claim token');
    await applyExecutionOutcomeTx(tx, { executionId: job.id, claimToken: token, expectedRevision: progress.revision,
      outcomeId: `review-failure:${args.identity}`, outcome: exhausted ? { kind: 'retry_exhausted', failure }
        : args.kind === 'decision_required' ? { kind: 'decision_required', failure }
        : { kind: 'review_retry', failure, claimKey: nextClaim, phase: args.phase } });
  }
  const status = args.kind === 'platform_failure' && !exhausted ? 'verifying' : 'attention';
  await tx.taskGraphNode.update({ where: { id: nodeId }, data: { status } });
  if (status === 'verifying') await tx.taskGraphRun.updateMany({ where: { id: node.runId, status: { not: 'paused' } }, data: { status: 'running' } });
  return status;
}

export async function graphRunCanStartTx(tx: Prisma.TransactionClient, runId: string): Promise<boolean> {
  await tx.$queryRaw`SELECT 1 AS locked FROM pg_advisory_xact_lock(hashtextextended(${'graph-control:' + runId}, 0))`;
  const run = await tx.taskGraphRun.findUniqueOrThrow({ where: { id: runId }, select: { status: true } });
  return run.status !== 'paused';
}

export async function requireGraphRunActiveTx(tx: Prisma.TransactionClient, runId: string) {
  if (!await graphRunCanStartTx(tx, runId)) throw new GraphRunPausedError(runId);
}

export async function requireGraphNodeActiveTx(tx: Prisma.TransactionClient, nodeId: string) {
  const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: nodeId }, select: { runId: true } });
  await requireGraphRunActiveTx(tx, node.runId);
}

export async function taskRunExitMatches(tx: Prisma.TransactionClient, taskRunId: string, proof?: TaskRunExitProof) {
  if (!proof || proof.taskRunId !== taskRunId || !proof.identity || proof.observation.kind !== 'exited') return false;
  return isDeepStrictEqual(proof.identity, await tx.taskRun.findUnique({ where: { id: taskRunId }, select: taskRunWriterIdentity }));
}

export async function currentWaitCause(job: TaskGraphExecution, progress: ExecutionProgress, db: Prisma.TransactionClient = prisma): Promise<ExecutionFailure | null> {
  const latest = await db.taskGraphEvent.findFirst({ where: { nodeId: job.nodeId, kind: { in: ['execution_outcome', 'implementation_blocked'] },
    payload: { path: ['executionId'], equals: job.id } }, orderBy: [{ createdAt: 'desc' }, { id: 'desc' }] });
  const payload = latest?.payload;
  if (!payload || typeof payload !== 'object' || Array.isArray(payload) || payload.claimToken !== job.claimToken) return null;
  if (latest.kind === 'implementation_blocked') {
    const result = payload.result;
    if (payload.taskRunId !== job.taskRunId || payload.checkpointCommit !== progress.candidateCommit ||
        !result || typeof result !== 'object' || Array.isArray(result) || typeof result.blockerKind !== 'string' || typeof result.note !== 'string') return null;
    return completeExecutionFailure({ code: result.blockerKind, detail: result.note });
  }
  const saved = executionProgress({ progress: payload.progress });
  if (!saved || saved.state !== progress.state || saved.candidateCommit !== progress.candidateCommit || saved.taskRunId !== progress.taskRunId) return null;
  const reservation = progress.conversation ? await db.taskGraphEvent.findUnique({ where: { id: progress.conversation.reservationId } }) : null;
  const reserved = reservation?.payload;
  const waitRevision = reserved && typeof reserved === 'object' && !Array.isArray(reserved) && typeof reserved.expectedRevision === 'number'
    ? reserved.expectedRevision : progress.revision;
  if (saved.revision !== waitRevision) {
    // Releasing the wait's phase worker advances the revision without starting a new wait.
    if (saved.revision + 1 !== waitRevision || !saved.worker || !await db.taskGraphEvent.count({ where: {
      nodeId: job.nodeId, kind: 'phase_worker_released', idempotencyKey: `execution-worker-released:${saved.worker.nonce}`,
      payload: { path: ['executionId'], equals: job.id } } })) return null;
  }
  const outcome = payload.outcome;
  if (!outcome || typeof outcome !== 'object' || Array.isArray(outcome)) return null;
  if (outcome.kind === 'waiting_for_user') {
    if (outcome.failure) return executionProgress({ progress: { ...saved, lastFailure: outcome.failure } })?.lastFailure || null;
    if (outcome.result === 'question' || outcome.result === 'answered') return { code: 'question', detail: saved.waitingMessage || 'Recorded ordinary question', requiresUserDecision: false };
    // Older permission waits lost their cause in this outcome; inspect the bound result rather than guessing from the note.
    if (!job.taskRunId || saved.taskRunId !== job.taskRunId) return null;
    const run = await db.taskRun.findUnique({ where: { id: job.taskRunId }, include: { participants: true } });
    if (run?.status !== 'completed') return null;
    try {
      const result = parseImplementationResult(run.participants[0]?.summary || run.summary || '');
      if (result.status === 'blocked') return completeExecutionFailure({ code: result.blockerKind, detail: result.note });
      if (result.status === 'waiting_for_user' || result.status === 'answered') return { code: 'question', detail: result.note, requiresUserDecision: false };
    } catch { return null; }
    return null;
  }
  return saved.lastFailure || null;
}

export async function writerSnapshotMatches(tx: Prisma.TransactionClient, proof: Awaited<ReturnType<typeof observeWriterSnapshot>>) {
  if (!proof.exited) return false;
  const jobs = await tx.taskGraphExecution.findMany({ where: { id: { in: proof.jobs.map(job => job.id) } }, orderBy: { id: 'asc' } });
  if (!isDeepStrictEqual(jobs, [...proof.jobs].sort((a, b) => a.id.localeCompare(b.id)))) return false;
  const runs = await tx.taskRun.findMany({ where: { id: { in: proof.taskRunIds } }, select: snapshotIdentity, orderBy: { id: 'asc' } });
  const identity = ({ status, participants, ...run }: (typeof proof.runs)[number]) => ({ ...run, status: lifecycle(status),
    participants: participants.map(({ status, ...participant }) => ({ ...participant, status: lifecycle(status) })) });
  return isDeepStrictEqual(runs.map(identity), proof.runs.map(identity));
}

