async function executeJob(runId: string, nodeKey: string, execution: TaskGraphExecution, claimToken: string) {
  const config = launchConfig(execution);
  const repair = await latestGraphRepair(execution.nodeId);
  const continuation = await latestImplementationRecovery(execution.nodeId);
  const persisted = executionProgress(execution.dispatchMetadata);
  const worker = persisted?.worker || await createGraphWriter();
  const checkpoint = persisted?.candidateCommit && persisted.workspaceBase
    ? { checkpointCommit: persisted.candidateCommit, workspaceBase: persisted.workspaceBase }
    : continuation && (!repair || continuation.createdAt > repair.createdAt)
      ? implementationCheckpoint(continuation.payload, execution.id) : null;
  const outcome = async (result: ExecutionOutcome) => {
    const current = await prisma.taskGraphExecution.findUniqueOrThrow({ where: { id: execution.id } });
    const progress = executionProgress(current.dispatchMetadata) || initialExecutionProgress();
    if (['repair_required', 'result_incomplete', 'platform_retry'].includes(result.kind) && 'failure' in result && result.failure && progress.candidateCommit) {
      const work = await continuationWorkFingerprint(execution.id, progress.candidateCommit);
      result = { ...result, failure: { ...result.failure,
        tree: await graphGit(execution.repository, 'rev-parse', '--verify', `${progress.candidateCommit}^{tree}`),
        fingerprint: result.kind === 'result_incomplete' ? work : createHash('sha256').update(work + ':' + (result.failure.checkId || result.failure.code)).digest('hex') } };
    }
    return applyExecutionOutcome({ executionId: execution.id, claimToken, expectedRevision: progress.revision,
      outcomeId: `${claimToken}:${progress.revision}:${result.kind}`, outcome: result });
  };
  try {
    await outcome({ kind: 'checkpoint', phase: persisted?.phase || 'prepare', worker });
    const { integration, workspace } = await withRepositoryLock(execution.repository, async () => {
      await requireGraphRunActive(runId);
      await assertExecutionOwnership(execution.id, claimToken);
      const integration = await ensureIntegrationRef({
        repoPath: execution.repository, runId, baseRef: execution.gitRef, baseCommit: execution.baseCommit,
      });
      let workspaceBase = integration.commit;
      if (repair && !checkpoint && execution.worktreePath) {
        // Dirty repairs keep their original baseline; final integration merges and checks the latest ref.
        if (!await graphGit(execution.worktreePath, 'status', '--porcelain', '--untracked-files=all')) {
          await graphGit(execution.worktreePath, 'merge', '--ff-only', integration.commit);
        } else workspaceBase = execution.baseCommit;
      }
      let resumeCommit = checkpoint?.checkpointCommit;
      if (persisted && checkpoint && execution.worktreeBranch) {
        let exists = true;
        try { await graphGit(execution.repository, 'show-ref', '--verify', '--quiet', execution.worktreeBranch); }
        catch (error) { if (error instanceof Error && 'code' in error && error.code === 1) exists = false; else throw error; }
        if (exists) {
          const tip = await graphGit(execution.repository, 'rev-parse', execution.worktreeBranch);
          await graphGit(execution.repository, 'merge-base', '--is-ancestor', checkpoint.checkpointCommit, tip);
          resumeCommit = tip;
        }
      }
      const workspace = await ensureJobWorktree({
        repoPath: execution.repository, runId, jobId: execution.id,
        baseRef: integration.ref, baseCommit: checkpoint?.workspaceBase || workspaceBase,
        worktreePath: execution.worktreePath || undefined,
        ...(resumeCommit ? { resumeCommit } : {}),
      });
      if (persisted?.lastFailure?.code === 'verification_input_changed') await graphGit(workspace.path, 'merge', '--ff-only', integration.commit);
      return { integration, workspace };
    });
    await requireGraphRunActive(runId);
    await assertExecutionOwnership(execution.id, claimToken);
    const implementationBase = await graphGit(workspace.path, 'rev-parse', 'HEAD');
    const workspaceContext = `本轮工作区候选：${implementationBase}。工作区基线：${workspace.baseCommit}。当前集成参考：${integration.commit}。` +
      '工作区候选与集成参考是独立引用，可以不同；在本轮候选上继续实施，平台在交付时受控合并，不要求先把工作区 HEAD 对齐到集成参考。';
    const { task, room } = await createChildTask(runId, nodeKey, execution, workspace.path);
    await recordExecutionDispatch({
      runId, nodeKey, executionKey: execution.key, claimToken,
      childTaskId: task.id, worktreePath: workspace.path, worktreeBranch: workspace.branch,
      dispatchMetadata: execution.worktreePath ? undefined : { ...immutableDispatchMetadata(execution.dispatchMetadata), integrationRef: integration.ref, workspaceBase: workspace.baseCommit, ...(checkpoint ? { resumedFrom: checkpoint.checkpointCommit, attemptId: continuation?.id } : {}) },
    });
    await outcome({ kind: 'checkpoint', phase: persisted?.phase || 'implement', workspaceBase: workspace.baseCommit, candidateCommit: implementationBase });
    const graphRun = await prisma.taskGraphRun.findUniqueOrThrow({ where: { id: runId }, select: { parentTaskId: true } });
    const snapshot = await prisma.taskGraphRun.findUniqueOrThrow({ where: { id: runId }, select: { snapshot: true } });
    const definition = snapshot.snapshot as unknown as GraphDefinition;
    const specInput = await prepareGraphSpecInput(definition);
    const implementOnly = definition.nodes.find((node) => node.key === nodeKey)?.executionMode === 'implement';
    await requestGraphChildTopic({
      parentTaskId: graphRun.parentTaskId, executionId: execution.id, childTaskId: task.id,
      title: task.name, workingDirectory: workspace.path,
    });
    const inputs = await prepareUpstreamInputs(execution.id);
    void postGraphParentProgress(graphRun.parentTaskId, runId,
      `${nodeKey}/${execution.key} 已启动。详细进度同步到仓库绑定群中的「${task.name}」子话题；投递期间记录仍保存在任务账本。`)
      .catch((error) => console.error('[TaskGraph] parent progress delivery failed:', error));
    await postTaskRoomMessage({
      roomId: room.id, userId: 'task-graph', userName: '任务图调度器',
      content: `执行 ${nodeKey}/${execution.key}。${workspaceContext}请在此 worktree 编辑代码并报告结果；平台负责受控提交，不要自行运行 git add/commit/merge。`,
    });
    const beforeRun = await prisma.taskGraphExecution.findUniqueOrThrow({ where: { id: execution.id } });
    const progress = executionProgress(beforeRun.dispatchMetadata)!;
    let receiptError = progress.lastFailure?.detail;
    if (progress.phase === 'collect_result' && !receiptError && progress.taskRunId) {
      const previous = await prisma.taskRun.findUnique({ where: { id: progress.taskRunId }, include: { participants: true } });
      if (previous?.taskId === task.id && previous.status === 'completed') {
        try { parseImplementationResult(previous.participants[0]?.summary || previous.summary || ''); }
        catch (error) { receiptError = error instanceof Error ? error.message : String(error); }
      }
    }
    const recoveryInstructions = progress.phase === 'collect_result'
      ? `\n上轮交付回执格式错误：${receiptError || '缺少有效交付结论，请核对 TASK_GRAPH_IMPLEMENTATION 契约'}。继续当前获批 Ticket 的正常实施：可修正回执、修改代码和测试或重新验证，由你判断下一步。只有确实完成目标才能返回合法 delivered；平台将重新固定当前 Worktree 候选，不复用旧候选代表本次交付。`
      : progress.lastFailure ? `\n本票自动回修：${JSON.stringify(progress.lastFailure)}\n使用保留的当前源码修复上述故障，并重新运行相同检查。` : '';
    const previousRepairRun = progress.conflictRepair && progress.runtimeDirectory && progress.taskRunId
      ? await prisma.taskRun.findUnique({ where: { id: progress.taskRunId }, include: { participants: true } }) : null;
    let reusableRepairRun: typeof previousRepairRun = null;
    if (previousRepairRun?.status === 'completed') {
      try {
        if (parseImplementationResult(previousRepairRun.participants[0]?.summary || previousRepairRun.summary || '').status === 'delivered') reusableRepairRun = previousRepairRun;
      } catch { /* An incomplete result needs fresh stage execution, not transport-success replay. */ }
    }
    const repairRuntime = progress.conflictRepair ? await prepareAcceptanceRuntime(execution.nodeId, `conflict:${claimToken}`,
      [{ repository: execution.repository, path: workspace.path, commit: progress.conflictRepair.candidateCommit }], reusableRepairRun ? progress.runtimeDirectory : undefined) : null;
    if (repairRuntime) await outcome({ kind: 'checkpoint', phase: 'integrate', runtimeDirectory: repairRuntime.directory });
    const dispatchProgress = executionProgress((await prisma.taskGraphExecution.findUniqueOrThrow({ where: { id: execution.id } })).dispatchMetadata)!;
    const storedRun = progress.conflictRepair ? reusableRepairRun
      : ['check', 'integrate'].includes(progress.phase) && progress.taskRunId
        ? await prisma.taskRun.findUnique({ where: { id: progress.taskRunId }, include: { participants: true } }) : null;
    if (storedRun && storedRun.status !== 'completed') throw new Error('Previous implementation TaskRun has no completed result');
    const inbox = storedRun ? [] : await conversationInputs(execution.id);
    const inputPrompt = conversationPrompt(inbox) + (inbox.length ? '\n' + await syncGraphConversationMaterials(task.id) : '');
    const plannedNode = definition.nodes.find(node => node.key === nodeKey)!;
    const ownsQuality = definition.deliveryContract === 'agent_owned_v1' && selfCheckExecution(plannedNode) === execution.key;
    const qualityChecks = ownsQuality ? graphReviewChecks(definition, nodeKey, await prisma.taskGraphExecution.findMany({ where: { nodeId: execution.nodeId } })).filter(check => check.id !== 'architecture:scope') : [];
    const qualityInstructions = ownsQuality ? `\n整票自查由本 execution 负责。${inputs.manifest.ticketInputs ? '其他执行已集成；结合当前可写工作区和固定输入清单验证完整组合。' : '其他执行尚未集成；可以先交付本仓，齐备后平台接续同一 Session 做整票自查。'}\n批准的整票命令（按 repository 找对应源码目录）：${JSON.stringify(plannedNode.acceptance.integrationChecks || [])}` +
      reviewResultInstructions('TASK_GRAPH_IMPLEMENTATION.ticketVerification', qualityChecks).replace('最终答复仅用一行 TASK_GRAPH_IMPLEMENTATION.ticketVerification', '在原 TASK_GRAPH_IMPLEMENTATION delivered 回执中增加 ticketVerification 字段，值为') : '';
    const stageDescription = (task.description || '') + '\n' + workspaceContext + specInput.instructions + inputs.instructions + qualityInstructions + (repairRuntime
        ? `\n受控冲突修复。原批准范围与上述 Spec/任务说明仍然有效；范围变化必须报告 blocked。源码只读：${workspace.path}。保留双方交付语义，解决 ${JSON.stringify(progress.conflictRepair)}。必须在本次 AP_GRAPH_OUTPUT_DIR 中写 resolution.json，格式 {"files":[{"path":"相对路径","content":"完整解决后文本"}]}，文件集合必须恰好是冲突路径。不要更改 Git 或源码，不要机械拼接；平台按本次 TaskRun 的产物回执读取解决文件、完成合并并重新检查和独立验收。输出 TASK_GRAPH_IMPLEMENTATION 结论。`
        : recoveryInstructions) + inputPrompt;
    const session = await implementationConversation(execution.id, config.participant);
    const result = storedRun ? { taskRunId: storedRun.id, status: storedRun.status, summary: storedRun.summary, participants: storedRun.participants } : await executeAcpxTaskRun({
      graphExecution: { executionId: execution.id, claimToken, revision: dispatchProgress.revision, inputIds: inbox.map(input => input.id) },
      taskSessionId: session.taskSessionId,
      taskId: task.id, taskName: task.name, taskDescription: stageDescription + session.context,
      extraReadOnlyPaths: [...specInput.paths, ...inputs.readOnlyPaths, ...(repairRuntime?.readOnlyPaths || [])],
      ...(repairRuntime ? { permissionConfig: repairRuntime.permissionConfig } : {}),
      orchestrationMode: 'single', participants: [session.participant], workingDirectory: repairRuntime?.directory || workspace.path,
    }).catch(error => {
      const preparation = runtimePreparationError(error);
      if (preparation) throw preparation;
      if (error instanceof AcpxRunStartupError && !transientPlatformCode(error)) throw new TaskInputPreparationError(`执行器启动失败（${error.taskRunId}）：${error.message}`, 'environment_failed');
      throw error;
    });
    await recordExecutionDispatch({ runId, nodeKey, executionKey: execution.key, claimToken, taskRunId: result.taskRunId });
    if (await graphRunIsPaused(runId)) return;
    const extra = await prepareExtraRepositories(definition.nodes.find(node => node.key === nodeKey)?.extraRepositories);
    const extraRepositoryState = await Promise.all(extra.details.map(async repo => ({ ...repo, workingTreeStatus: (await graphGit(repo.repository, 'status', '--porcelain', '--untracked-files=all')).slice(0, 8000) })));
    if (extraRepositoryState.length) await prisma.taskGraphEvent.create({ data: { runId, nodeId: execution.nodeId,
      idempotencyKey: `execution:${execution.id}:extra-repos:${claimToken}`, kind: 'extra_repository_state', payload: { executionId: execution.id, taskRunId: result.taskRunId, repositories: extraRepositoryState } } });
    if (result.status !== 'completed') {
      const serviceFailure = await prisma.taskGraphEvent.findFirst({ where: { nodeId: execution.nodeId, kind: 'service_attempt_failed', payload: { path: ['taskRunId'], equals: result.taskRunId } } });
      if (serviceFailure) throw new TaskInputPreparationError('临时联调服务启动或运行失败，见本次服务回执；不是业务材料缺失', 'environment_failed', 'service_runtime');
      throw new Error(`Agent execution ended: ${result.status}: ${result.summary}`);
    }
    if (progress.conflictRepair) {
      if ((await observeTaskRunWriter(result.taskRunId)).kind !== 'exited') throw new TaskGraphGitError('ownership_mismatch', 'Conflict repair writer has not demonstrably exited; preserve source and resolution artifact', workspace.path);
      const resolution = parseImplementationResult(result.participants[0]?.summary || result.summary || '');
      if (resolution.status === 'blocked') {
        await outcome({ kind: 'decision_required', failure: { code: resolution.blockerKind, detail: resolution.note,
          action: '保留待完成合并，补齐所述材料、能力或明确范围决定后再解决冲突', owner: resolution.blockerKind === 'environment_failed' ? 'platform' : 'user',
          requiresUserDecision: resolution.blockerKind !== 'environment_failed', affectedPaths: progress.conflictRepair.paths } });
        await refreshTaskGraphRunStatus(runId); return;
      }
    }
    const candidate = await withRepositoryLock(execution.repository, async () => {
      await requireGraphRunActive(runId);
      await assertExecutionOwnership(execution.id, claimToken);
      if (progress.conflictRepair && repairRuntime) return finishConflictRepair({
        repoPath: execution.repository, runId, jobId: execution.id, baseCommit: workspace.baseCommit, integrationRef: integration.ref,
        checkpoint: progress.conflictRepair, resolutionFile: await conflictResolutionFile({ nodeId: execution.nodeId, taskId: task.id, taskRunId: result.taskRunId }),
        approvedCommits: await approvedConflictCommits(runId, execution.repository),
        assertOwnership: () => assertExecutionOwnership(execution.id, claimToken).then(() => undefined),
      });
      return commitJobWorktree({
        repoPath: execution.repository, runId, jobId: execution.id, message: `Task graph candidate ${nodeKey}/${execution.key}`,
      });
    });
    const candidateProgress = await outcome({ kind: 'checkpoint', phase: 'implement', candidateCommit: candidate, workspaceBase: workspace.baseCommit, ...(progress.conflictRepair ? { conflictRepair: null } : {}) });
    let conclusion;
    try { conclusion = parseImplementationResult(result.participants[0]?.summary || result.summary || '', { conversation: candidateProgress.phase === 'implement' && !progress.conflictRepair, reviewChecks: qualityChecks }); }
    catch (error) { conclusion = { status: 'invalid' as const, blockerKind: 'invalid_result' as const, note: error instanceof Error ? error.message : String(error) }; }
    if (conclusion.status !== 'delivered') {
      if (conclusion.status === 'working') {
        await outcome({ kind: 'continue_work', note: conclusion.note, fingerprint: await continuationWorkFingerprint(execution.id, candidate) });
      } else if (conclusion.status === 'waiting_for_user' || conclusion.status === 'answered') {
        await outcome({ kind: 'waiting_for_user', note: conclusion.note, result: conclusion.status === 'answered' ? 'answered' : 'question' });
      } else if (conclusion.status === 'invalid') {
        await outcome({ kind: 'result_incomplete', failure: { code: 'invalid_result', detail: conclusion.note } });
      } else {
        await pauseGraphImplementation({ runId, nodeKey, executionId: execution.id, claimToken,
          checkpointCommit: candidate, workspaceBase: workspace.baseCommit, taskRunId: result.taskRunId, result: conclusion });
      }
      await refreshTaskGraphRunStatus(runId);
      void postGraphChildProgress(task.id, `implementation-outcome-${claimToken}`,
        conclusion.status === 'working' ? `本轮进度已保存，原 Agent 继续工作：${conclusion.note}` : conclusion.status === 'invalid' ? '实施成果已保存，自动补收交付结论；尚未交付。' : conclusion.note)
        .catch(error => console.error('[TaskGraph] outcome delivery failed:', error));
      return;
    }
    await reconcileConversationDeliveries();
    if (!await sealConversationTurn(execution.id, claimToken, candidate)) {
      await refreshTaskGraphRunStatus(runId); return;
    }
    let checks: CheckResult[] = [];
    const latest = await withRepositoryLock(execution.repository, async () => {
      await requireGraphRunActive(runId);
      await assertExecutionOwnership(execution.id, claimToken);
      return ensureIntegrationRef({ repoPath: execution.repository, runId, baseRef: execution.gitRef, baseCommit: execution.baseCommit });
    });
    const beforeIntegration = executionProgress((await prisma.taskGraphExecution.findUniqueOrThrow({ where: { id: execution.id } })).dispatchMetadata);
    const integrated = await integrateJobWithRetry({
      repoPath: execution.repository, runId, jobId: execution.id,
      integrationRef: latest.ref, expectedIntegrationCommit: latest.commit, baseCommit: workspace.baseCommit,
      maxAttempts: Math.max(1, 3 - (beforeIntegration?.integrationAttempts || 0)),
      assertOwnership: async () => {
        await requireGraphRunActive(runId);
        await assertExecutionOwnership(execution.id, claimToken);
        if (progress.conflictRepair) await assertConflictIntegrationBaseline({ repoPath: execution.repository, runId,
          baseCommit: workspace.baseCommit, integrationRef: latest.ref, checkpoint: progress.conflictRepair,
          approvedCommits: await approvedConflictCommits(runId, execution.repository) });
      },
      onRetry: async (failure) => {
        await outcome({ kind: 'checkpoint', phase: 'integrate', candidateCommit: await graphGit(workspace.path, 'rev-parse', 'HEAD') });
        await outcome({ kind: 'integration_stale', failure: { code: 'integration_stale', detail: JSON.stringify(failure.integration) } });
      },
      verify: async (staging) => {
        await outcome({ kind: 'checkpoint', phase: 'integrate', candidateCommit: await graphGit(staging, 'rev-parse', 'HEAD') });
        checks = await runChecks(implementOnly || definition.deliveryContract === 'agent_owned_v1' ? [] : config.checks, staging, { ...inputs.env, AP_GRAPH_SERVICE_TASK_ID: task.id, AP_GRAPH_WRITER_NONCE: worker.nonce }, inputs.readOnlyPaths);
      },
    });
    if (ownsQuality &&
        (progress.conflictRepair || await graphGit(execution.repository, 'rev-parse', `${candidate}^{tree}`) !== await graphGit(execution.repository, 'rev-parse', `${integrated.commit}^{tree}`))) {
      await outcome({ kind: 'repair_required', failure: { code: 'verification_input_changed', detail: '集成或冲突解决改变了已自查的源码；在原 Coding Session 对当前最终源码补验，再交付。' } });
      return;
    }
    await outcome({ kind: 'integrated', commit: integrated.commit,
      evidence: { checks, implementation: conclusion, extraRepositories: extraRepositoryState, taskRunId: result.taskRunId, integratedCommit: integrated.commit,
        ...(ownsQuality && inputs.manifest.ticketInputs ? { ticketInputs: [...inputs.manifest.ticketInputs, { executionId: execution.id, commit: integrated.commit }].sort((a, b) => a.executionId.localeCompare(b.executionId)) } : {}) },
    });
    void postGraphParentProgress(graphRun.parentTaskId, runId,
      `${nodeKey}/${execution.key} 已集成 ${integrated.commit.slice(0, 12)}`)
      .catch((error) => console.error('[TaskGraph] parent progress delivery failed:', error));
    await markNodeIntegrationsReady(runId, nodeKey);
  } catch (error) {
    if (await graphRunIsPaused(runId)) return;
    const detail = error instanceof Error ? error.message : String(error);
    const kind = error instanceof TaskInputPreparationError ? 'input_preparation_failed'
      : error instanceof TaskGraphGitError ? error.code : checkFailure(error) ? 'test_failed' : 'dispatch_failed';
    const current = await prisma.taskGraphExecution.findUnique({ where: { id: execution.id } });
    if (current?.status === 'claimed') {
      const preparation = runtimePreparationError(error);
      if (preparation) {
        const saved = executionProgress(current.dispatchMetadata)!;
        if (current.worktreePath && !saved.conflictRepair) {
          const candidateCommit = await withRepositoryLock(execution.repository, async () => {
            await requireGraphRunActive(runId);
            await assertExecutionOwnership(execution.id, claimToken);
            return commitJobWorktree({ repoPath: execution.repository, runId, jobId: execution.id, message: `Runtime preparation checkpoint ${nodeKey}/${execution.key}` });
          });
          await outcome({ kind: 'checkpoint', phase: saved.phase, candidateCommit });
        }
        await outcome({ kind: preparation.kind === 'transient' ? 'platform_retry' : 'decision_required', failure: { ...preparation.failure, blockedPhase: 'input_preparation',
          ...(preparation.kind === 'transient' ? { blockerCause: 'transient' as const } : {}) } });
      } else if (error instanceof TaskInputPreparationError && current.worktreePath) {
        const checkpointCommit = executionProgress(current.dispatchMetadata)?.conflictRepair?.candidateCommit || await withRepositoryLock(execution.repository, async () => {
          await requireGraphRunActive(runId);
          await assertExecutionOwnership(execution.id, claimToken);
          return commitJobWorktree({
            repoPath: execution.repository, runId, jobId: execution.id, message: `Input preparation checkpoint ${nodeKey}/${execution.key}`,
          });
        });
        await pauseGraphImplementation({ runId, nodeKey, executionId: execution.id, claimToken, checkpointCommit,
          workspaceBase: executionProgress(current.dispatchMetadata)?.workspaceBase || (isRecord(current.dispatchMetadata) && typeof current.dispatchMetadata.workspaceBase === 'string' ? current.dispatchMetadata.workspaceBase : execution.baseCommit),
          taskRunId: current.taskRunId || 'not-created', blockedPhase: error.blockedPhase,
          result: { status: 'blocked', blockerKind: error.blockerKind, note: detail } });
      } else {
        const failedCheck = checkFailure(error);
        if (failedCheck) {
          await requireGraphRunActive(runId);
          await assertExecutionOwnership(execution.id, claimToken);
          const candidateCommit = await withRepositoryLock(execution.repository, async () => {
            await requireGraphRunActive(runId);
            await assertExecutionOwnership(execution.id, claimToken);
            return commitJobWorktree({
              repoPath: execution.repository, runId, jobId: execution.id, message: `Checked candidate ${nodeKey}/${execution.key}`,
            });
          });
          await outcome({ kind: 'checkpoint', phase: 'check', candidateCommit });
          await outcome({ kind: 'repair_required', failure: {
          code: 'test_failed', checkId: `execution:${execution.key}:${failedCheck.check.name}`,
          command: failedCheck.check.argv, detail: failedCheck.detail,
        } });
        } else if (error instanceof TaskGraphGitError) {
          const failure = { code: error.integration?.kind === 'ownership_mismatch' ? 'ownership_mismatch' : error.code,
            detail: error.integration ? JSON.stringify({ message: detail, integration: error.integration }) : detail };
          if (error.integration?.kind === 'conflict') {
            try {
              if (current.taskRunId && (await observeTaskRunWriter(current.taskRunId)).kind !== 'exited') throw new Error('Previous implementation writer has not exited');
              const saved = executionProgress(current.dispatchMetadata)!;
              const metadata = isRecord(current.dispatchMetadata) ? current.dispatchMetadata : {};
              if (typeof metadata.integrationRef !== 'string') throw new Error('Missing approved integration ref');
              const conflict = error.integration;
              const checkpoint = await withRepositoryLock(execution.repository, async () => prepareConflictRepair({
                repoPath: execution.repository, runId, jobId: execution.id, baseCommit: saved.workspaceBase || execution.baseCommit,
                integrationRef: metadata.integrationRef as string, evidence: conflict, approvedCommits: await approvedConflictCommits(runId, execution.repository),
                assertOwnership: () => assertExecutionOwnership(execution.id, claimToken, saved.revision).then(() => undefined),
              }));
              await outcome({ kind: 'repair_required', conflictRepair: checkpoint, failure: { ...failure, action: '在原任务范围内解决所列文本冲突，平台完成合并并复验', owner: 'implementer', requiresUserDecision: false, affectedPaths: checkpoint.paths } });
            } catch (repairError) {
              await outcome({ kind: 'decision_required', failure: { ...failure, detail: `${failure.detail}\n${repairError instanceof Error ? repairError.message : String(repairError)}`,
                action: '平台核验原执行者退出证据及账本中的候选、合并父提交与当前集成引用；保留待完成合并，由受控合并步骤处理所列文件', owner: 'platform', requiresUserDecision: false, affectedPaths: error.integration.paths } });
            }
          } else await outcome({ kind: error.code === 'integration_retry_exhausted' ? 'retry_exhausted' : 'decision_required', failure });
        } else {
          const temporary = transientPlatformCode(error);
          await outcome({ kind: 'platform_retry', failure: { code: kind, detail,
            owner: 'platform', requiresUserDecision: false,
            ...(temporary ? { fingerprint: temporary } : {}), action: '保留当前工作与原会话继续；相同输入无进展时停止空转',
          } });
        }
      }
      const latest = await prisma.taskGraphExecution.findUniqueOrThrow({ where: { id: execution.id } });
      const progress = executionProgress(latest.dispatchMetadata);
      const state = latest.status === 'ready' ? '正在自动修复或重试，无需人工继续。'
        : progress?.state === 'exhausted' ? '自动处理已达上限，保留现场和失败证据。'
        : progress?.lastFailure && graphFailureSummary(progress.lastFailure, progress.state).requiresUserDecision ? '需要你确认下方具体请求。' : '平台正在处理，现场和证据已保留。';
      if (current.childTaskId) await postGraphChildProgress(current.childTaskId, `issue-${claimToken}`,
        `${nodeKey}/${execution.key}：${state}\n${progress?.lastFailure ? formatGraphFailureSummary(progress.lastFailure, progress.state) : '平台将补充处理说明。'}`)
        .catch((deliveryError) => console.error('[TaskGraph] child issue delivery failed:', deliveryError));
    } else {
      console.error(`[TaskGraph] verification failed after integration ${runId}/${nodeKey}:`, error);
    }
    await refreshTaskGraphRunStatus(runId);
    const graphRun = await prisma.taskGraphRun.findUniqueOrThrow({ where: { id: runId }, select: { parentTaskId: true } });
    const finalJob = await prisma.taskGraphExecution.findUniqueOrThrow({ where: { id: execution.id } });
    const finalProgress = executionProgress(finalJob.dispatchMetadata);
    const status = finalJob.status === 'ready' ? '正在自动修复或重试，无需人工继续。'
      : finalProgress?.state === 'exhausted' ? '自动处理已达上限，现场已保留。'
      : finalProgress?.lastFailure && graphFailureSummary(finalProgress.lastFailure, finalProgress.state).requiresUserDecision ? '需要你确认一项具体请求。' : '待平台处理，无需你决定技术细节。';
    void postGraphParentProgress(graphRun.parentTaskId, runId, `${nodeKey}/${execution.key}：${status}详情见仓库群原任务话题。`)
      .catch((deliveryError) => console.error('[TaskGraph] parent progress delivery failed:', deliveryError));
  } finally {
    await releaseGraphExecutionWorker(execution.id, claimToken, worker.nonce);
  }
}

export async function pauseGraphImplementation(args: {
  runId: string; nodeKey: string; executionId: string; claimToken: string;
  checkpointCommit: string; workspaceBase: string; taskRunId: string; blockedPhase?: 'implementation' | 'input_preparation' | 'service_runtime';
  result: Extract<ImplementationResult, { status: 'blocked' }> | { status: 'invalid'; note: string; blockerKind: 'invalid_result' };
}) {
  const current = await prisma.taskGraphExecution.findUniqueOrThrow({ where: { id: args.executionId } });
  let progress = executionProgress(current.dispatchMetadata);
  if (progress && (progress.candidateCommit !== args.checkpointCommit || !progress.workspaceBase)) {
    progress = await applyExecutionOutcome({ executionId: args.executionId, claimToken: args.claimToken,
      expectedRevision: progress.revision, outcomeId: `${args.claimToken}:${progress.revision}:paused-candidate`,
      outcome: { kind: 'checkpoint', phase: progress.phase, candidateCommit: args.checkpointCommit, workspaceBase: progress.workspaceBase || args.workspaceBase },
    });
  }
  if (progress && progress.phase === 'implement' && (args.blockedPhase || 'implementation') === 'implementation' && args.result.blockerKind === 'environment_failed') {
    const { inspectImplementationConditions } = await import('./preparation-recovery');
    const run = await prisma.taskGraphRun.findUniqueOrThrow({ where: { id: args.runId } });
    try {
      await inspectImplementationConditions(current, progress, run.snapshot as unknown as GraphDefinition, args.runId);
    } catch (error) {
      const preparation = error instanceof RuntimePreparationError ? error : null;
      return applyExecutionOutcome({ executionId: args.executionId, claimToken: args.claimToken, expectedRevision: progress.revision,
        outcomeId: `${args.claimToken}:${progress.revision}:environment-checked`,
        outcome: { kind: preparation?.kind === 'transient' ? 'platform_retry' : 'decision_required',
          failure: { ...preparation?.failure, code: 'environment_failed',
            detail: redactSensitiveText(`${args.result.note}\n准备核实：${error instanceof Error ? error.message : String(error)}`),
            blockedPhase: 'implementation', owner: 'platform', requiresUserDecision: false,
            ...(preparation ? { blockerCause: preparation.kind === 'transient' ? 'transient' as const : 'missing_capability' as const } : {}),
          } },
      });
    }
  }
  if (progress && progress.phase === 'implement' && (args.blockedPhase || 'implementation') === 'implementation') return applyExecutionOutcome({
    executionId: args.executionId, claimToken: args.claimToken, expectedRevision: progress.revision,
    outcomeId: `${args.claimToken}:${progress.revision}:engineering-work`,
    outcome: ['permission_required', 'scope_change'].includes(args.result.blockerKind)
      ? { kind: 'waiting_for_user', note: args.result.note, failure: { code: args.result.blockerKind, detail: args.result.note, blockedPhase: 'implementation', owner: 'user', requiresUserDecision: true } }
      : { kind: 'continue_work', note: args.result.note, fingerprint: await continuationWorkFingerprint(args.executionId, args.checkpointCommit) },
  });
  if (progress) return applyExecutionOutcome({ executionId: args.executionId, claimToken: args.claimToken,
    expectedRevision: progress.revision, outcomeId: `${args.claimToken}:${progress.revision}:decision_required`,
    outcome: { kind: args.result.blockerKind === 'environment_failed' && args.result.status === 'blocked' && args.result.blockerCause === 'transient' ? 'platform_retry' : 'decision_required',
      failure: { code: args.result.blockerKind, detail: args.result.note, blockedPhase: args.blockedPhase || 'implementation',
        ...(args.result.status === 'blocked' && args.result.blockerCause ? { blockerCause: args.result.blockerCause } : {}),
        ...(['permission_required', 'scope_change'].includes(args.result.blockerKind) ? { owner: 'user' as const, requiresUserDecision: true } : {}),
        ...(['environment_failed', 'missing_upstream_input'].includes(args.result.blockerKind) ? { owner: 'platform' as const, requiresUserDecision: false,
          action: args.result.status === 'blocked' && args.result.blockerCause === 'transient' ? '按已有预算重试暂时平台故障' : '准备并验证缺少的运行能力后从已保存候选继续；环境不变时不重复实施' } : {}) } },
  });
  return prisma.$transaction(async tx => {
    const job = await tx.taskGraphExecution.findUniqueOrThrow({ where: { id: args.executionId } });
    await tx.$queryRaw`SELECT id FROM "TaskGraphNode" WHERE id = ${job.nodeId} FOR UPDATE`;
    const node = await tx.taskGraphNode.findUniqueOrThrow({ where: { id: job.nodeId } });
    if (node.runId !== args.runId || node.key !== args.nodeKey) throw new Error('Implementation target mismatch');
    if (job.status !== 'claimed' || job.claimToken !== args.claimToken) throw new Error('Implementation claim mismatch');
    await tx.taskGraphEvent.create({ data: { runId: args.runId, nodeId: job.nodeId,
      idempotencyKey: `execution:${job.id}:implementation:${args.claimToken}`, kind: 'implementation_blocked',
      payload: { recoveryKind: 'implementation', blockedPhase: args.blockedPhase || 'implementation', executionId: job.id,
        checkpointCommit: args.checkpointCommit, workspaceBase: args.workspaceBase, taskRunId: args.taskRunId,
        claimToken: args.claimToken, result: args.result } } });
    await tx.taskGraphExecution.update({ where: { id: job.id }, data: { status: 'attention', issueKind: args.result.blockerKind } });
    await tx.taskGraphNode.update({ where: { id: job.nodeId }, data: { status: 'attention' } });
  });
}

export async function observeExecutionWriter(job: { dispatchMetadata: unknown; taskRunId: string | null }): Promise<WriterObservation> {
  const progress = executionProgress(job.dispatchMetadata);
  if (!progress) return { kind: 'unknown', reason: 'Execution has no versioned writer identity' };
  if (progress.worker) {
    const observation = await observeGraphWriter(progress.worker, Boolean(progress.workerReleasedAt));
    if (observation.kind !== 'exited') return observation;
  }
  const taskRunId = job.taskRunId || (progress.worker ? progress.taskRunId : undefined);
  if (progress.conversation?.kind === 'running') {
    const conversation = await observeTaskRunWriter(progress.conversation.taskRunId);
    if (conversation.kind !== 'exited') return conversation;
  }
  if (taskRunId) return observeTaskRunWriter(taskRunId);
  return progress.worker ? { kind: 'exited' } : { kind: 'unknown', reason: 'Claim has no durable current TaskRun writer' };
}

export async function observeTaskRunWriter(taskRunId: string): Promise<WriterObservation> {
  const run = await prisma.taskRun.findUnique({ where: { id: taskRunId }, include: { participants: true } });
  if (!run || !run.participants.length || run.participants.some(participant => participant.executionBackend !== 'platform_local' || !['codex', 'kimi-code'].includes(participant.harnessType || ''))) return { kind: 'unknown', reason: 'Writer backend has no local process proof' };
  try {
    const metadata: unknown = JSON.parse(run.controlMetadata || '{}');
    const writer = metadata && typeof metadata === 'object' ? parseGraphWriter(Reflect.get(metadata, 'graphWriter')) : null;
    const release: unknown = metadata && typeof metadata === 'object' ? Reflect.get(metadata, 'graphWriterReleased') : undefined;
    const released = Boolean(writer && release && typeof release === 'object' && Reflect.get(release, 'nonce') === writer.nonce && typeof Reflect.get(release, 'at') === 'string' && Number.isFinite(Date.parse(Reflect.get(release, 'at'))));
    return observeGraphWriter(writer, released);
  } catch (error) { return { kind: 'unknown', reason: error instanceof Error ? error.message : String(error) }; }
}

export async function prepareDeclaredRuntime(args: { workspace: string; approvedReadOnlyRoots: string[]; outputDirectory: string; priorArtifacts?: PriorOutputArtifact[]; writerNonce?: string; sourceDeclaration?: RuntimeDeclarationSource | null; resourceWorkspace?: string; strictReadOnlyRoots?: boolean; probeScope?: RuntimeProbeScope }): Promise<PreparedRuntime> {
  const empty: PreparedRuntime = { identity: '', manifestHash: '', readOnlyPaths: [], env: {}, instructions: '', receipt: null, verifiedResources: [] };
  let declaration: Awaited<ReturnType<typeof runtimeDeclaration>>;
  try { declaration = args.sourceDeclaration === undefined ? await runtimeDeclaration(args.workspace) : args.sourceDeclaration; }
  catch (error) { throw new RuntimePreparationError('invalid', error instanceof Error ? error.message : String(error), [path.join(args.workspace, '.agent-platform/runtime.json')]); }
  if (!declaration) return empty;
  const approved = await Promise.all([args.workspace, ...args.approvedReadOnlyRoots].map(root => fs.realpath(root))).catch(error => { throw new RuntimePreparationError('invalid', `已批准运行目录不可用：${error instanceof Error ? error.message : String(error)}`, args.approvedReadOnlyRoots, declaration.manifestHash); });
  const manifestHash = declaration.manifestHash;
  const resources: { kind: string; path: string; sha256: string; origin: RuntimeResource }[] = [];
  const resolve = async (ref: RuntimeResource, kind: string) => {
    const output = ref.kind === 'output' ? args.priorArtifacts?.find(artifact => artifact.eventId === ref.eventId) : undefined;
    if (ref.kind === 'output' && !output) throw new RuntimePreparationError('missing', `尚未绑定运行资源产物事件：${ref.eventId}`, [ref.relativePath], manifestHash);
    let target: string;
    if (ref.kind === 'output') { if (!output) throw new RuntimePreparationError('missing', `尚未绑定运行资源产物事件：${ref.eventId}`, [ref.relativePath], manifestHash); target = path.join(output.directory, ref.relativePath); }
    else target = path.resolve(args.resourceWorkspace || args.workspace, ref.path);
    if (!approved.some(root => within(root, target))) throw new RuntimePreparationError('invalid', `${kind} 资源超出已批准目录：${target}`, [target], manifestHash);
    let canonical: string;
    try { canonical = await fs.realpath(target); }
    catch (error) { if (error instanceof Error && 'code' in error && error.code === 'ENOENT') throw new RuntimePreparationError('missing', `缺少 ${kind} 资源：${target}`, [target], manifestHash); throw error; }
    if (canonical !== target || !approved.some(root => within(root, canonical))) throw new RuntimePreparationError('invalid', `${kind} 资源超出已批准目录或使用链接：${target}`, [target], manifestHash);
    const sha256 = await runtimeResourceDigest(canonical);
    if (sha256 !== ref.sha256) throw new RuntimePreparationError('invalid', `${kind} 资源 SHA256 与版本化声明不一致：${target}`, [target], manifestHash);
    resources.push({ kind, path: target, sha256, origin: ref }); return target;
  };
  const env: Record<string, string> = {};
  const skills: { skill: NonNullable<RuntimeDeclarationSource['declaration']['skills']>[number]; packageRoot: string; dependencies: { id: string; package: string; requiredFiles: string[] }[] }[] = [];
  try {
    if (declaration.declaration.postgres) await resolve(declaration.declaration.postgres.resource, 'PostgreSQL');
    if (declaration.declaration.ocr) {
      const ocr = declaration.declaration.ocr;
      const weights = await resolve(ocr.weights, 'OCR 权重');
      for (const file of ocr.requiredFiles) {
        const filename = path.join(weights, file);
        const required = await fs.lstat(filename).catch(error => { if (error.code === 'ENOENT') return null; throw error; });
        if (!required?.isFile() || await fs.realpath(filename) !== filename) throw new RuntimePreparationError('missing', `OCR 必需文件不可用：${filename}`, [filename], manifestHash);
      }
      env.AP_GRAPH_OCR_MODEL_DIR = weights;
    }
    if (declaration.declaration.browser) {
      env.AP_GRAPH_BROWSER_MODULE = await resolve(declaration.declaration.browser.module, 'Playwright 模块');
      env.AP_GRAPH_BROWSER_EXECUTABLE = await resolve(declaration.declaration.browser.executable, 'Chromium 可执行文件');
      env.TMPDIR = '/tmp';
      env.PLAYWRIGHT_MODULE = env.AP_GRAPH_BROWSER_MODULE; env.PLAYWRIGHT_CHROMIUM_EXECUTABLE = env.AP_GRAPH_BROWSER_EXECUTABLE;
    }
    for (const skill of declaration.declaration.skills || []) {
      const packageRoot = await resolve(skill.package, `技能 ${skill.id}`);
      const hostRoots = await Promise.all(args.approvedReadOnlyRoots.map(root => fs.realpath(root)));
      if (within(args.workspace, packageRoot) || !hostRoots.includes(packageRoot)) throw new RuntimePreparationError('invalid', '技能包必须有明确的宿主只读目录授权，不能由仓内声明自授', [packageRoot], manifestHash);
      const dependencies = [];
      for (const dependency of skill.dependencies || []) {
        const directory = await resolve(dependency.package, `技能依赖 ${dependency.id}`);
        if (within(args.workspace, directory) || !hostRoots.includes(directory)) throw new RuntimePreparationError('invalid', '技能依赖必须逐包获得明确宿主只读授权', [directory], manifestHash);
        dependencies.push({ id: dependency.id, package: directory, requiredFiles: dependency.requiredFiles });
      }
      skills.push({ skill, packageRoot, dependencies });
    }
  } catch (error) {
    if (error instanceof RuntimePreparationError) throw error;
    throw new RuntimePreparationError('invalid', error instanceof Error ? error.message : String(error), resources.map(resource => resource.path), manifestHash);
  }
  const identity = createHash('sha256').update(JSON.stringify({ manifestHash, resources: resources.map(({ kind, sha256, origin }) => ({ kind, sha256, origin })) })).digest('hex');
  env.AP_GRAPH_RUNTIME_IDENTITY = identity;
  const probeIdentity = createHash('sha256').update(JSON.stringify({ identity, resources })).digest('hex');
  const verified = await reuseRuntimeProbes(args.probeScope, probeIdentity, async () => {
    let browserVersion: string | undefined;
    const skillChecks: SkillVerification[] = [];
    for (const skill of skills) {
      const probeEnv = { ...process.env, ...env, AP_TASK_SANDBOX: '1', AP_SANDBOX_MODEL_ACCESS: '0', AP_PROJECT_REPOSITORY: args.resourceWorkspace || args.workspace, HOME: args.outputDirectory, TMPDIR: '/tmp', AP_GRAPH_OUTPUT_DIR: args.outputDirectory,
        AP_GRAPH_OUTPUT_BINDINGS_JSON: JSON.stringify([{ source: args.outputDirectory, target: args.outputDirectory, readOnly: false }]) };
      try { skillChecks.push(await verifySkillResource({ ...skill, workspace: args.workspace, readOnlyPaths: approved, env: probeEnv })); }
      catch (error) { throw new RuntimePreparationError('missing', `技能完整包预检失败：${error instanceof Error ? error.message : String(error)}`, [skill.packageRoot], identity); }
    }
    if (declaration.declaration.browser) {
      const script = 'const{chromium}=require(process.env.AP_GRAPH_BROWSER_MODULE);(async()=>{const b=await chromium.launch({headless:true,executablePath:process.env.AP_GRAPH_BROWSER_EXECUTABLE,args:["--no-sandbox","--disable-background-networking"]});try{const p=await b.newPage();await p.setContent("<title>ap-runtime-ready</title>");if(await p.title()!=="ap-runtime-ready")throw Error("browser smoke failed");process.stdout.write(JSON.stringify({version:b.version()}))}finally{await b.close()}})().catch(e=>{console.error(e.message);process.exitCode=1})';
      const probeEnv = { ...process.env, ...env, ...(args.writerNonce ? { AP_GRAPH_WRITER_NONCE: args.writerNonce } : {}), AP_TASK_SANDBOX: '1', AP_SANDBOX_MODEL_ACCESS: '0', AP_PROJECT_REPOSITORY: args.resourceWorkspace || args.workspace, HOME: args.outputDirectory, TMPDIR: '/tmp', XDG_CACHE_HOME: args.outputDirectory, AP_GRAPH_OUTPUT_DIR: args.outputDirectory, AP_GRAPH_OUTPUT_BINDINGS_JSON: JSON.stringify([{ source: args.outputDirectory, target: args.outputDirectory, readOnly: false }]) };
      const wrapped = wrapWithBubblewrap({ command: process.execPath, commandArgs: ['-e', script], cwd: args.workspace, workspaceRoot: args.workspace, sandboxMode: 'read-only', networkAccess: 'restricted', readOnlyPaths: approved, strictReadOnlyRoots: args.strictReadOnlyRoots, env: probeEnv });
      try {
        const result = await execute(wrapped.command, wrapped.args, { cwd: args.workspace, env: probeEnv, timeout: 20_000, maxBuffer: 128 * 1024 });
        const parsed: unknown = JSON.parse(result.stdout); if (!parsed || typeof parsed !== 'object' || !('version' in parsed) || typeof parsed.version !== 'string') throw new Error('浏览器预检没有有效回执'); browserVersion = parsed.version;
      } catch (error) {
        const code: unknown = error && typeof error === 'object' ? Reflect.get(error, 'code') : undefined;
        const timedOut = error && typeof error === 'object' && Reflect.get(error, 'killed') === true;
        const transient = timedOut || ['EAI_AGAIN', 'ECONNRESET', 'ETIMEDOUT', 'ECONNREFUSED'].includes(String(code));
        throw new RuntimePreparationError(transient ? 'transient' : 'missing', `浏览器启动预检失败：${String(error && typeof error === 'object' && Reflect.get(error, 'stderr') || (error instanceof Error ? error.message : error)).slice(-4000)}`, resources.map(resource => resource.path), identity);
      }
    }
    for (const resource of resources) if (await runtimeResourceDigest(resource.path) !== resource.sha256) throw new RuntimePreparationError('invalid', '运行资源在预检期间改变', [resource.path], identity);
    return { ...(browserVersion ? { browserVersion } : {}), skills: skillChecks };
  });
  for (const resource of resources) if (await runtimeResourceDigest(resource.path) !== resource.sha256) throw new RuntimePreparationError('invalid', '运行资源在预检期间改变', [resource.path], identity);
  const receipt: RuntimePreflightReceipt = { version: 1, identity, manifestHash, commit: declaration.commit, resources, ...(verified.browserVersion ? { browserVersion: verified.browserVersion } : {}), ...(verified.skills.length ? { skills: verified.skills } : {}) };
  await fs.writeFile(path.join(args.outputDirectory, `runtime-preflight-${identity}.json`), JSON.stringify(receipt, null, 2) + '\n');
  return { identity, manifestHash, readOnlyPaths: approved.filter(root => root !== args.workspace).concat(resources.map(resource => resource.path)), env, receipt, verifiedResources: resources,
    instructions: `\n运行能力已按${declaration.origin === 'host_registration' ? '平台显式登记' : '仓内版本化声明'}预检，资源身份 ${identity}。浏览器和 OCR 路径见 AP_GRAPH_RUNTIME_* / AP_GRAPH_BROWSER_* / AP_GRAPH_OCR_MODEL_DIR；这些资源只读，缓存和报告写本阶段输出目录。` +
      (verified.skills.length ? `\n本次可用技能包：${JSON.stringify(skills.map(({ skill, packageRoot, dependencies }) => ({ id: skill.id, path: packageRoot, entrypoints: skill.requiredFiles.filter(file => path.basename(file) === 'SKILL.md'), dependencies })))}` : '') };
}
